const products=[
{slug:'dark-monsoon',name:'Dark Monsoon',notes:'Amber • Agar Wood Oil • Suede',topNotes:['Amber','Saffron','Thyme','Raspberry'],heartNotes:['Agar Wood Oil','Frankincense','Jasmine'],baseNotes:['Suede','Amber','Leather','Sandalwood'],subtitle:'The Power After the Storm',description:'Deep, atmospheric and quietly commanding. Dark Monsoon captures the feeling of rain settling into the earth — where freshness meets depth and oud leaves behind a powerful, lingering presence.',mood:'Powerful',character:'Deep • Earthy • Mysterious',image:'/products/dark Monsoon.webp',infographic:'/products/dark Monsoon 2.webp',gallery:['/products/dark-monsoon-box.webp','/products/dark Monsoon.webp','/products/dark Monsoon 2.webp','/products/the-luxury-experience.webp','/products/the-five-vows.webp'],accent:'#afb7a8',price:1499,gender:'Male'},
{slug:'royal-zafran-rose',name:'Royal Zafran Rose',notes:'Bergamot • Saffron Pure • Saffron Musk',topNotes:['Bergamot','Pear','Melon','Gardenia','Peach','Mandarin Orange'],heartNotes:['Saffron Pure','Jasmine','Lily of the Valley','Tuberose','Orchid','Plum','Violet'],baseNotes:['Saffron Musk','Cedar','Musk','Vanilla','Blackberry'],subtitle:'A Rose, Made Royal.',story:['In the deepest winter, when the world holds its breath, royalty once gathered around fires that burned not for warmth, but for ritual. Saffron strands were dropped into rose water, and agarwood chips smoldered slowly, releasing smoke that carried prayers into the night.','Royal Zafran Rose is that ritual, captured.','It opens with the spice of Kashmiri saffron, warm and golden. The heart reveals a rose garden at midnight—dark, velvety, unapologetic. The base is aged agarwood, deep and resinous, like a memory you cannot forget.','This is not a fragrance for the crowd. It is for the one who walks into a room and does not need to speak.'],description:'An opulent interpretation of timeless rose, enriched with the warmth of zafran and the depth of agarwood. Rich, elegant and unmistakably regal.',mood:'Regal',character:'Rich • Floral • Opulent',image:'/products/royal zefran rose.webp',infographic:'/products/royal zefran rose 2.webp',gallery:['/products/royal-zafran-rose-box.webp','/products/royal zefran rose.webp','/products/royal zefran rose 2.webp','/products/the-luxury-experience.webp','/products/the-five-vows.webp'],accent:'#c8aca2',price:1499,gender:'Unisex'},
{slug:'golden-ritual',name:'Golden Ritual',notes:'Tea • Jasmine • Vanilla',topNotes:['Tea','Osmanthus','Bergamot'],heartNotes:['Jasmine','Rose','Freesia','Orange Blossom','Orchid'],baseNotes:['Musk','Vanilla','Patchouli'],subtitle:'Warmth Becomes a Ritual.',story:['Before winter fully arrives, there is a season of golden evenings. The sun sets earlier, but the light is softer. Fires are lit not for survival, but for comfort. Coffee is brewed slowly. Vanilla pods are split open, their scent filling the air like a promise.','Golden Ritual is that glow.','It opens with the richness of cold-brewed coffee—dark, bitter, intoxicating. The heart is vanilla, creamy and sweet, but not childish. The base is amber, glowing like the last embers of a fire that refuses to die.','This is a fragrance for the one who finds luxury in comfort, not in show.'],description:'The comforting richness of coffee meets smooth vanilla and glowing amber. Warm, enveloping and intimate — a fragrance inspired by the rituals we return to again and again.',mood:'Comforting',character:'Warm • Sweet • Intimate',image:'/products/golden ritual.webp',infographic:'/products/golden ritual 2.webp',gallery:['/products/golden-ritual-box.webp','/products/golden ritual.webp','/products/golden ritual 2.webp','/products/the-luxury-experience.webp','/products/the-five-vows.webp'],accent:'#c8aa72',price:1499,gender:'Unisex'},
{slug:'golden-leaf',name:'Golden Leaf',notes:'Bergamot • Agarwood • Tonka Bean',topNotes:['Bergamot','Saffron'],heartNotes:['Agarwood','Rose'],baseNotes:['Tonka Bean','Sugar','Amber','White Musk','Oakmoss'],subtitle:'Wrapped in Golden Warmth.',story:['Summer in India is not just heat. It is abundance.','Golden honey drips from combs in the Western Ghats. Tobacco leaves dry in the sun in Andhra Pradesh, their scent smoky and sweet. Tonka beans, cured for months, release a fragrance like vanilla, almond, and hay combined.','Golden Leaf is summer\'s indulgence, bottled.','It opens with tobacco—smoky, masculine, confident. The heart is honey, wild and golden, not cloying. The base is tonka, sweet but sophisticated, like a dessert meant for adults.','This is a fragrance for the one who enjoys the finer things, without apology.'],description:'A rich tobacco accord softened by honey and the smooth warmth of tonka. Confident and refined, Golden Leaf leaves a warm impression that stays close to the skin.',mood:'Bold',character:'Warm • Refined • Confident',image:'/products/golden leaf.webp',infographic:'/products/golden leaf 2.webp',gallery:['/products/golden-leaf-box.webp','/products/golden leaf.webp','/products/golden leaf 2.webp','/products/the-luxury-experience.webp','/products/the-five-vows.webp'],accent:'#b89a5e',price:1499,gender:'Male'},
{slug:'crystal-bloom',name:'Crystal Bloom',notes:'Sea Water • Jasmine • Cedar',topNotes:['Sea Water','Lavender','Rosemary','Mint','Coriander'],heartNotes:['Jasmine','Geranium','Neroli'],baseNotes:['Cedar','Oakmoss','White Musk','Ambergris'],subtitle:'Where Water Becomes a Flower.',story:['The first light of morning does not simply brighten the world—it awakens its clarity.','Cool sea water moves beneath the dawn. Lavender, rosemary, and mint rise with the breeze, while jasmine and neroli begin to bloom in the quiet air. Beneath the freshness, cedar and white musk create a clean, elegant foundation that remains softly on the skin.','Crystal Bloom captures the feeling of a new beginning—fresh, luminous, and quietly confident. It is for the person who carries freshness not as an impression, but as a way of being.','Within The Sixth Ritu, it is the moment when spring becomes memory—the meeting of clear water, blooming flowers, and light that lingers long after morning has passed.'],description:'Clean, luminous and effortlessly fresh. Crystal Bloom evokes clear water, open air and delicate flowers awakening in the first light of morning.',mood:'Fresh',character:'Clean • Luminous • Airy',image:'/products/crystal bloom.webp',infographic:'/products/crystal bloom 2.webp',gallery:['/products/crystal-bloom-box.webp','/products/crystal bloom.webp','/products/crystal bloom 2.webp','/products/the-luxury-experience.webp','/products/the-five-vows.webp'],accent:'#b4cdd1',price:1499,gender:'Male'},
{slug:'flora-silk',name:'Flora Silk',notes:'Bergamot • Rose • Musk',topNotes:['Bergamot','Coffee','Lemon'],heartNotes:['Rose','Fruity','Jasmine'],baseNotes:['Musk','Sandalwood','Vanilla','Amber'],subtitle:'Flowers, Draped in Silk.',story:['A flower does not need to speak to be remembered—it leaves its presence in the air.','Soft petals unfold one after another. A graceful bouquet of jasmine, rose, and delicate florals fills the room, while gentle woods and musk create the impression of silk against the skin. Every note feels smooth, refined, and effortlessly beautiful.','Flora Silk captures the elegance of a bouquet wrapped in fine fabric—a fragrance that feels feminine, graceful, and timeless. It is for the woman whose presence is soft, yet impossible to forget.','Within The Sixth Ritu, it is the moment when flowers become memory—the meeting of delicate petals, quiet luxury, and a beauty that remains after the bouquet is gone.','Flora Silk — Elegance, woven in flowers.'],description:'A graceful bouquet inspired by the softness of petals against silk. Delicate yet memorable, Flora Silk expresses understated elegance through a beautifully composed floral character.',mood:'Elegant',character:'Soft • Floral • Graceful',image:'/products/flora silk.webp',infographic:'/products/flora silk 2.webp',gallery:['/products/flora-silk-box.webp','/products/flora silk.webp','/products/flora silk 2.webp','/products/the-luxury-experience.webp','/products/the-five-vows.webp'],accent:'#cfbdc6',price:1499,gender:'Female'}];
const reviews={'dark-monsoon':[{name:'Arjun M.',rating:5,date:'Aug 2026',text:'Opens with a rush of something dark and wet — like stepping into a forest after heavy rain. By the drydown it\'s all oud and warm earth. Wore it to a dinner party and my friend asked me three times what I was wearing.',verified:true},{name:'Priya K.',rating:5,date:'Jul 2026',text:'Not for the faint-hearted. This one announces you before you enter a room. I save it for evenings when I want to feel commanding.',verified:true},{name:'Vikram S.',rating:4,date:'Jul 2026',text:'The longevity is insane. Sprayed it on my kurta before a wedding and could still smell traces of it two days later.',verified:true},{name:'Meera R.',rating:5,date:'Jun 2026',text:'My husband rarely notices fragrances but this one stopped him mid-conversation. He actually borrowed it the next day.',verified:true},{name:'Rahul D.',rating:4,date:'Jun 2026',text:'Beautiful blend but needs a couple of hours to settle. The opening is a bit sharp, but once it calms down, it\'s magnificent.',verified:false}],'royal-zafran-rose':[{name:'Ananya S.',rating:5,date:'Aug 2026',text:'This is what I imagine a Mughal garden smells like at sunset. The saffron gives it a warmth that elevates the rose beyond anything I\'ve tried.',verified:true},{name:'Kavya P.',rating:5,date:'Jul 2026',text:'Bought this for my mother\'s birthday. She called me in tears — said it reminded her of her grandmother\'s home. That\'s the kind of fragrance this is.',verified:true},{name:'Deepak J.',rating:4,date:'Jul 2026',text:'Elegant without being old-fashioned. I wore it to an art gallery opening and felt perfectly dressed.',verified:true},{name:'Ritu M.',rating:5,date:'Jun 2026',text:'The rose here isn\'t sweet or powdery — it\'s regal and complex. You can feel the saffron weaving through it like a gold thread.',verified:true},{name:'Nikhil B.',rating:4,date:'May 2026',text:'A bit too floral for casual wear. But for weddings, celebrations, evenings out — absolutely perfect.',verified:false}],'golden-ritual':[{name:'Shreya T.',rating:5,date:'Aug 2026',text:'This is my comfort fragrance. Coffee and vanilla without smelling like a dessert — it\'s warm and sophisticated. My morning ritual now starts with two sprays.',verified:true},{name:'Aman G.',rating:5,date:'Jul 2026',text:'Reminds me of Sunday mornings with filter coffee and old songs. Not trying to be loud, just quietly beautiful.',verified:true},{name:'Rohan K.',rating:5,date:'Jul 2026',text:'My girlfriend stole my bottle after trying it once. Had to order another one for myself. Take that as the highest compliment.',verified:true},{name:'Pooja N.',rating:4,date:'Jun 2026',text:'Perfect winter fragrance. The amber base keeps it grounded while the vanilla gives it just enough sweetness.',verified:true},{name:'Aditya V.',rating:4,date:'May 2026',text:'Wore it on a first date. Three dates later, she said she fell in love with the scent before she fell in love with me.',verified:false}],'golden-leaf':[{name:'Sanjay R.',rating:5,date:'Aug 2026',text:'The tobacco note here is nothing like cigarette smoke — it\'s smooth, almost leathery. Combined with the honey, it creates something truly distinctive.',verified:true},{name:'Ishaan M.',rating:5,date:'Jul 2026',text:'I keep reaching for this one when I need confidence. Job interviews, presentations, important meetings — Golden Leaf is my silent partner.',verified:true},{name:'Tara L.',rating:4,date:'Jun 2026',text:'Sophisticated without being stuffy. My colleagues keep asking what I\'m wearing and I keep dodging the question.',verified:true},{name:'Karthik S.',rating:5,date:'Jun 2026',text:'The drydown is extraordinary — warm tonka and a hint of something resinous that stays close to skin.',verified:true},{name:'Nandini D.',rating:4,date:'May 2026',text:'Slightly masculine-leaning but I wear it confidently as a woman. The honey softens everything beautifully.',verified:false}],'crystal-bloom':[{name:'Anita W.',rating:5,date:'Aug 2026',text:'Opens slightly fresh on my skin and settles into a very soft floral scent. I wore it to dinner and could still smell it on my clothes the next morning.',verified:true},{name:'Raj P.',rating:4,date:'Jul 2026',text:'This is the fragrance equivalent of stepping out of a shower into a garden. Clean but alive.',verified:true},{name:'Sonal K.',rating:5,date:'Jul 2026',text:'Perfect for Indian summers when everything else feels too heavy. Crystal Bloom breathes.',verified:true},{name:'Aarav M.',rating:4,date:'Jun 2026',text:'My go-to for office wear. Professional without being boring, fresh without being generic.',verified:true},{name:'Divya S.',rating:5,date:'May 2026',text:'Subtler than the other Sixth Ritu fragrances but that\'s its strength. People lean in closer — which is exactly the point.',verified:false}],'flora-silk':[{name:'Meghna J.',rating:5,date:'Aug 2026',text:'Like wearing a silk dupatta made of flowers. This fragrance drapes rather than projects, and that elegance is what makes it special.',verified:true},{name:'Farah A.',rating:5,date:'Jul 2026',text:'Bought this sight unseen based on the description and wasn\'t disappointed. Delicate but present — you notice it the way you notice someone graceful entering a room.',verified:true},{name:'Priyanka S.',rating:4,date:'Jun 2026',text:'I\'ve been searching for a fragrance that feels feminine without being sweet. Flora Silk is exactly that.',verified:true},{name:'Ankit R.',rating:4,date:'Jun 2026',text:'Applied it before a long flight. Eight hours later, a flight attendant complimented me on it. The lasting power surprised me given how light it feels.',verified:true},{name:'Sunita V.',rating:5,date:'May 2026',text:'My mother says it smells like the jasmines she grew up with, but more refined. I think that\'s the perfect description.',verified:false}]};
if('scrollRestoration' in history)history.scrollRestoration='manual';const route=location.pathname.replace(/\/index\.html$/,'').replace(/\/$/,'')||'/';const app=document.querySelector('#app');let cart=JSON.parse(localStorage.getItem('tsr-cart')||'[]');let wishes=JSON.parse(localStorage.getItem('tsr-wishes')||'[]');let coupon=localStorage.getItem('tsr-coupon')||'';let couponInfo=JSON.parse(localStorage.getItem('tsr-coupon-info')||'null');let activeMood=0;let slide=0;let heroPaused=false;var cmsPages={};var cmsPopup=null;let combos=JSON.parse(localStorage.getItem('tsr-combos')||'[]');let activeOffers=[];let instagramPosts=[];
const link=(path,label,cls='')=>`<a class="${cls}" href="${path}" data-link>${label}</a>`;const bySlug=s=>products.find(p=>p.slug===s);function regularSubtotal(){const comboSlugs=new Set();combos.forEach(c=>c.slugs.forEach(s=>comboSlugs.add(s)));return cart.reduce((a,i)=>comboSlugs.has(i.slug)?a:a+bySlug(i.slug).price*i.qty,0)}function calcCouponDisc(){if(!coupon||!couponInfo)return 0;const sub=hasCombo()?regularSubtotal():cart.reduce((a,i)=>a+bySlug(i.slug).price*i.qty,0);if(sub<=0)return 0;if(couponInfo.dt==='percentage'){let d=Math.round(sub*couponInfo.d/100);if(couponInfo.mx>0)d=Math.min(d,Math.round(couponInfo.mx/100));return Math.min(d,sub)}let d=Math.round(couponInfo.d/100);return Math.min(d,sub)}function couponLabel(){if(!coupon||!couponInfo)return'';if(couponInfo.dt==='percentage')return couponInfo.d+'% off';return'₹'+Math.round(couponInfo.d/100)+' off'}const money=()=>'';const persist=()=>{localStorage.setItem('tsr-cart',JSON.stringify(cart));localStorage.setItem('tsr-wishes',JSON.stringify(wishes));localStorage.setItem('tsr-coupon',coupon);if(couponInfo)localStorage.setItem('tsr-coupon-info',JSON.stringify(couponInfo));else localStorage.removeItem('tsr-coupon-info');localStorage.setItem('tsr-combos',JSON.stringify(combos));};
function header(){return `<div class="announcement"><span>Discover The Sixth Ritu — A New Season of Fine Fragrance</span></div><header class="header"><button class="icon-btn mobile-menu" data-menu aria-label="Open menu">${icons.menu}</button><a class="brand" href="/" data-link><img src="/logo.png" alt="The Sixth Ritu" /></a><nav class="nav" aria-label="Primary navigation">${link('/','Home')}${link('/shop','Shop')}${link('/collection','The Collection')}${link('/about','Our Story')}${link('/the-sixth-ritu','The Sixth Ritu')}${link('/contact','Contact')}</nav><div class="tools"><button class="icon-btn" data-search aria-label="Search">${icons.search}</button>${link('/account',icons.user,'icon-btn')}<button class="icon-btn" data-wishlist aria-label="Wishlist">${icons.heart}</button><button class="icon-btn" data-cart aria-label="Bag">${icons.bag}<span class="count">${cart.reduce((a,i)=>a+i.qty,0)}</span></button></div></header><div class="menu-panel" id="menu"><button class="icon-btn close-menu" data-menu aria-label="Close menu">×</button><a class="brand" href="/" data-link><img src="/logo.png" alt="The Sixth Ritu" /></a><nav>${link('/','Home')}${link('/shop','Shop')}${link('/collection','The Collection')}${link('/about','Our Story')}${link('/the-sixth-ritu','The Sixth Ritu')}${link('/contact','Contact')}${link('/wishlist','Wishlist')}${link('/cart','Bag')}</nav></div>`}
function footer(){return `<section class="newsletter section"><div class="container newsletter-grid"><div><p class="eyebrow">Enter the world of The Sixth Ritu</p><h2 class="display">Stay in the Season.</h2></div><div><p>Be the first to discover new creations, private releases and stories from The Sixth Ritu.</p><form class="email-form" data-newsletter><input aria-label="Your email address" type="email" placeholder="Your Email Address" required/><button>Join →</button></form><p class="form-note">By subscribing, you agree to receive communications from The Sixth Ritu.</p></div></div></section><footer class="footer"><div class="container"><div class="footer-top"><div class="footer-brand"><img src="/logo.png" alt="The Sixth Ritu"/><p>Fragrances inspired by emotion, created to become memory.</p></div><div><h3>Shop</h3>${products.map(p=>link('/product/'+p.slug,p.name)).join('')}</div><div><h3>Discover</h3>${link('/about','Our Story')}${link('/the-sixth-ritu','The Sixth Ritu')}${link('/collection','Our Philosophy')}${link('/contact','Contact Us')}</div><div><h3>Customer Care</h3>${link('/shipping','Shipping & Delivery')}${link('/returns','Returns & Exchanges')}${link('/faq','FAQs')}${link('/track-order','Track Order')}</div></div><div class="footer-bottom"><span>© 2026 The Sixth Ritu. All Rights Reserved.</span><span>${link('/privacy','Privacy')} &nbsp; ${link('/terms','Terms')}</span></div></div></footer>`}
function productCard(p){const hd=p.mrp&&p.mrp>p.price;const cardImg=p.gallery?p.gallery[0]:p.image;const hoverImgs=p.gallery?p.gallery.slice(0,3):[];return `<div class="v3-prod-card"${hoverImgs.length>1?` data-hover-imgs='${JSON.stringify(hoverImgs)}'`:''}><div class="v3-prod-card-img">${hd?'<span class="v3-prod-card-badge">Sale</span>':''}<button class="card-wish ${wishes.includes(p.slug)?'active':''}" data-wish="${p.slug}" aria-label="Save ${p.name}">${icons.heart}</button><a href="/product/${p.slug}" data-link><img src="${cardImg}" alt="${p.name}" loading="lazy"/></a></div><h3><a href="/product/${p.slug}" data-link>${p.name}</a></h3><p class="v3-prod-card-char">${p.character}</p><p class="v3-prod-card-spec">Extrait de Parfum · 50 ML</p><p class="v3-prod-card-price">${hd?`<del>₹${p.mrp.toLocaleString('en-IN')}</del> `:''}₹${p.price.toLocaleString('en-IN')}</p><div class="v3-prod-card-actions"><button data-add="${p.slug}">Add to Bag</button><button data-quick="${p.slug}">Quick View</button></div></div>`}
function home(){let p=products[0];return `<main id="main"><section class="hero" aria-label="The Sixth Ritu introduction">${[0,1,2].map((i)=>{let hp=products[[0,1,4][i]];let copy=[['THE SIXTH RITU','A Season Beyond the Six.','India has always known six seasons. We created one more — a season experienced through scent.','Discover The Collection','/collection','Our Story','/about'],['THE COLLECTION','Six Fragrances. Six Stories.','From rain-soaked earth and royal rose to golden amber and delicate florals, discover moments that remain with you.','Explore All Fragrances','/shop','',''],['FINE FRAGRANCE • INDIAN IMAGINATION • MODERN LUXURY','Made to Be Remembered.','Not simply a fragrance you wear, but a feeling that becomes part of your story.','Find Your Ritu','#find','','']][i];return `<div class="hero-slide ${i===0?'active':''}"><div class="hero-copy"><p class="eyebrow">${copy[0]}</p><h1 class="display">${copy[1]}</h1><p>${copy[2]}</p><div class="hero-actions">${link(copy[4],copy[3],'btn')}${copy[6]?link(copy[6],copy[5],'btn btn-light'):''}</div></div><div class="hero-product"><img src="${hp.image}" alt="${hp.name} fragrance" /></div></div>`}).join('')}<div class="hero-ui"><div class="dots">${[0,1,2].map(i=>`<button class="dot ${i===0?'active':''}" data-slide="${i}" aria-label="Show slide ${i+1}"></button>`).join('')}</div><div class="hero-arrows"><button data-slide-prev aria-label="Previous slide">←</button><button data-slide-next aria-label="Next slide">→</button></div></div></section><section class="section"><div class="container intro"><div><p class="eyebrow">Welcome to The Sixth Ritu</p><h2 class="display">Some Seasons Change the World.<br/>Others Stay With You.</h2></div><div class="intro-body"><p>India has always known six seasons — Vasanta, Grishma, Varsha, Sharad, Hemanta and Shishira. Each transforms the world around us and leaves behind a feeling.</p><p>We imagine another. A season found in the scent of rain after a storm, the warmth of an evening ritual, flowers resting on silk, or the memory of someone after they have gone.</p>${link('/about','Discover Our Story','text-link')}</div></div></section><section class="signature section"><div class="container"><div class="section-head"><div><p class="eyebrow">The Signature Collection</p><h2 class="display">Discover Your Ritu.</h2></div><p>Six distinctive fragrances. Six different moods. Created for the moments you want to remember.</p></div><div class="feature-rail" id="feature"><div class="feature-image"><img src="${p.image}" alt="${p.name} fragrance"/></div><div class="feature-details"><span class="feature-no">01 — 06</span><p class="notes">${p.notes}</p><h3 class="display">${p.name}</h3><h4>${p.subtitle}</h4><p>${p.description}</p>${link('/product/'+p.slug,'Explore '+p.name,'text-link')}<div class="rail-nav">${products.map((x,i)=>`<button class="${i===0?'active':''}" data-feature="${i}">${String(i+1).padStart(2,'0')}</button>`).join('')}</div></div></div></div></section><section class="mood" id="find"><div class="container mood-grid"><div class="mood-copy"><p class="eyebrow">Choose by Mood</p><h2 class="display">What Is Your Ritu Today?</h2><p>I want something...</p><div class="mood-list">${products.map((p,i)=>`<button class="mood-choice ${i===0?'active':''}" data-mood="${i}">${p.mood}</button>`).join('')}</div></div><div class="mood-visual"><img src="${p.image}" alt="${p.name} fragrance"/><div class="mood-caption"><h3>${p.name}</h3><p>${p.character}</p></div></div></div></section><section class="seasons"><div class="seasons-content"><p class="eyebrow">The Inspiration</p><h2 class="display">India Knows<br/>Six Seasons.</h2><div class="season-list"><span>VASANTA<small>New Beginnings</small></span><span>GRISHMA<small>Heat & Radiance</small></span><span>VARSHA<small>Rain & Renewal</small></span><span>SHARAD<small>Clarity</small></span><span>HEMANTA<small>Golden Warmth</small></span><span>SHISHIRA<small>Stillness</small></span></div><p>And Then, There Is One More.</p><div class="seasons-final">THE SIXTH RITU</div><p>A season without a date. A season experienced through scent.</p>${link('/the-sixth-ritu','Discover The Sixth Ritu','text-link')}</div></section><section class="philosophy"><div class="philosophy-copy"><p class="eyebrow">Our Philosophy</p><h2 class="display">Made to Be Worn.<br/>Created to Be Remembered.</h2><p>Every fragrance begins with a feeling. We translate that feeling through scent — bringing together Indian imagination, expressive perfume ingredients and a contemporary approach to luxury.</p>${link('/the-sixth-ritu','Our Philosophy','text-link')}</div><div class="philosophy-art"><img src="${products[2].image}" alt="Golden Ritual fragrance" loading="lazy"/></div></section><section class="campaign"><div class="campaign-content"><p class="eyebrow">The Season of Luxury</p><h2 class="display">A Memory Has No Season.</h2>${link('/collection','Explore The Collection','btn')}</div></section><section class="section"><div class="container"><div class="section-head"><div><p class="eyebrow">Shop by Character</p><h2 class="display">Find a Fragrance That Feels Like You.</h2></div></div><div class="character-grid">${products.map(p=>`<a class="character" href="/product/${p.slug}" data-link><h3>${p.mood} &<br/>${p.character.split(' • ')[1]||'Memorable'}</h3><p>Explore ${p.name} →</p></a>`).join('')}</div></div></section><section class="section"><div class="container art"><div class="art-text"><p class="eyebrow">The Art of Fragrance</p><h2 class="display">More Than a Fragrance. A Personal Ritual.</h2><p>A fragrance becomes meaningful through the moments connected to it. A first impression. A familiar evening. A celebration. A journey. A person.</p></div><div class="art-quote">The Sixth Ritu is created for those moments — fragrances designed to become part of your presence and, eventually, part of your memory.</div></div></section><section class="section"><div class="container"><div class="section-head"><div><p class="eyebrow">The Collection</p><h2 class="display">Six expressions of one idea.</h2></div>${link('/shop','Shop All','text-link')}</div><div class="product-grid">${products.map(productCard).join('')}</div></div></section><section class="statement"><blockquote>“We do not create fragrances merely to be worn. We create them to be remembered.”</blockquote><cite>— The Sixth Ritu</cite></section><section class="section social"><div class="container"><div class="social-head"><div><p class="eyebrow">Follow the Season</p><h2 class="display">@TheSixthRitu</h2></div><a href="#newsletter" class="text-link">Follow Our Journey</a></div><div class="social-rack"><div class="social-piece"><img src="${products[1].image}" alt="Royal Zafran Rose" loading="lazy"/></div><div class="social-piece"><img src="${products[4].image}" alt="Crystal Bloom" loading="lazy"/></div><div class="social-piece"><img src="${products[5].image}" alt="Flora Silk" loading="lazy"/></div></div></div></section></main>`}
function pageHero(kicker,title,copy=''){return `<section class="page-hero"><div class="container"><p class="eyebrow">${kicker}</p><h1 class="display">${title}</h1>${copy?`<p>${copy}</p>`:''}</div></section>`}
function shop(){return `<main id="main">${pageHero('The Signature Collection','Discover Your Ritu.','Six distinctive fragrances. Six different moods. Created for the moments you want to remember.')}<div class="container"><p class="crumb"><a href="/" data-link>Home</a> / Shop</p></div>${comboSection()}<section class="section"><div class="container"><div class="shop-toolbar"><span>${products.length} fragrances</span><label>Gender <select class="select" data-filter-gender><option value="all">All</option><option value="Male">For Him</option><option value="Female">For Her</option><option value="Unisex">Unisex</option></select></label><label>Sort <select class="select" data-sort><option value="name">Collection order</option><option value="az">Name: A–Z</option></select></label></div><div class="product-grid" id="shop-grid">${products.map(productCard).join('')}</div></div></section></main>`}
function reviewSection(p){const pr=reviews[p.slug]||[];if(!pr.length)return '';const avg=(pr.reduce((a,r)=>a+r.rating,0)/pr.length).toFixed(1);const counts=[5,4,3,2,1].map(s=>pr.filter(r=>r.rating===s).length);return `<section class="product-reviews section"><div class="container"><div class="reviews-header"><div><h2 class="display">Reviews</h2><div class="reviews-summary-block"><span class="reviews-big-score">${avg}</span><div><div class="reviews-stars-lg">${'★'.repeat(Math.round(avg))}${'☆'.repeat(5-Math.round(avg))}</div><span class="reviews-count-text">${pr.length} Review${pr.length===1?'':'s'}</span></div></div></div><div class="reviews-bars">${counts.map((c,i)=>`<div class="review-bar"><span>${5-i}★</span><div class="bar"><div class="bar-fill" style="width:${pr.length?Math.round(c/pr.length*100):0}%"></div></div><span>${c}</span></div>`).join('')}</div></div><button class="review-write-btn" data-write-review>Write a Review</button><div class="reviews-list">${pr.map(r=>`<div class="review-card"><div class="review-card-top"><div class="review-card-stars">${'★'.repeat(r.rating)}${'☆'.repeat(5-r.rating)}</div><div class="review-card-meta"><span class="review-card-author">${r.name}</span><span>${r.date}</span>${r.verified?'<span class="review-verified">✓ Verified Purchase</span>':''}</div></div><p class="review-card-text">${r.text}</p></div>`).join('')}</div><div class="review-form-wrap" id="review-form" style="display:none"><h3>Write a Review</h3><form data-review-form><div class="review-rating-row"><span>Your Rating</span><div class="review-star-input">${[1,2,3,4,5].map(s=>`<button type="button" data-star="${s}" aria-label="${s} star${s>1?'s':''}" class="">☆</button>`).join('')}</div></div><div class="field"><label for="rev-name">Name</label><input id="rev-name" placeholder="Your name" required/></div><div class="field"><label for="rev-title">Review Title</label><input id="rev-title" placeholder="Sum it up" required/></div><div class="field"><label for="rev-text">Your Review</label><textarea id="rev-text" rows="4" placeholder="Share your experience..." required></textarea></div><button class="btn" type="submit">Submit Review</button></form></div></div></section>`}
function videoSection(){return `<section class="section"><div class="container"><div class="section-head"><div><p class="eyebrow">Experience the Fragrance</p><h2 class="display">See the Season.</h2></div></div><div class="video-grid"><div class="video-card"><span class="video-play"></span></div></div></div></section>`}
const productFAQs={'dark-monsoon':[{q:'Is Dark Monsoon suitable for daily wear?',a:'Dark Monsoon is a bold, commanding fragrance best suited for evenings, special occasions, and cooler weather. For daily wear, one spray is usually sufficient to maintain a subtle presence without overwhelming.'},{q:'How long does Dark Monsoon last on skin?',a:'As an Extrait de Parfum with 20–40% concentration, Dark Monsoon typically lasts 8–12 hours on skin. The oud and amber base notes are especially long-lasting and may linger on clothing even longer.'},{q:'What occasions is Dark Monsoon best for?',a:'Dark Monsoon excels at evening events, formal dinners, weddings, and winter gatherings. Its deep, atmospheric character makes a memorable impression in settings where you want to feel powerful and distinctive.'}],'royal-zafran-rose':[{q:'Is Royal Zafran Rose for men or women?',a:'Royal Zafran Rose is a unisex fragrance. The saffron and rose combination transcends gender — it is regal and complex, designed for anyone who appreciates opulent, sophisticated scent.'},{q:'Does the rose smell sweet or powdery?',a:'The rose in Royal Zafran Rose is neither sweet nor powdery. It is rich, dark, and velvety, elevated by saffron and grounded by cedar and musk. Think of a rose garden at midnight rather than a bouquet of fresh-cut flowers.'},{q:'Can I wear Royal Zafran Rose in summer?',a:'While Royal Zafran Rose is at its finest in cooler weather, one light spray can work in summer for evening events. In heat, its saffron and floral heart project beautifully without becoming heavy.'}],'golden-ritual':[{q:'Does Golden Ritual smell like coffee?',a:'Golden Ritual opens with a tea note rather than coffee, alongside osmanthus and bergamot. The composition is warm and comforting but sophisticated — more like the atmosphere of a quiet morning ritual than a specific beverage.'},{q:'Is Golden Ritual too sweet for the office?',a:'Not at all. The vanilla and patchouli base give warmth rather than overt sweetness. Golden Ritual is well balanced and sits close to the skin, making it appropriate for professional settings and daytime wear.'},{q:'What makes Golden Ritual a good everyday fragrance?',a:'Its moderate projection, comforting character, and versatile warm-sweet profile make it appropriate for most settings. It is neither too bold for daytime nor too light for evening, making it one of the most versatile choices in the collection.'}],'golden-leaf':[{q:'What does the tobacco note smell like?',a:'The tobacco note in Golden Leaf is smooth, warm, and slightly sweet — reminiscent of cured tobacco leaves rather than cigarette smoke. It blends with honey-like tonka bean to create a refined, masculine warmth.'},{q:'Is Golden Leaf appropriate for younger wearers?',a:'Golden Leaf appeals to anyone who appreciates distinguished, warm fragrances regardless of age. Its bergamot and saffron top notes keep it feeling contemporary, while the agarwood and tonka base add depth.'},{q:'How does Golden Leaf compare to Dark Monsoon?',a:'Both are warm, masculine-leaning fragrances, but they differ in character. Dark Monsoon is deeper and more atmospheric with its oud and amber, while Golden Leaf is warmer and smoother with its tonka and agarwood. Dark Monsoon commands a room; Golden Leaf draws people closer.'}],'crystal-bloom':[{q:'Is Crystal Bloom a masculine fragrance?',a:'Crystal Bloom is classified as masculine but its fresh, clean character appeals to many regardless of gender. The sea water and jasmine heart with cedar base creates something universally appealing — like fresh air itself.'},{q:'How does Crystal Bloom perform in hot weather?',a:'Crystal Bloom is one of the best performers in heat. Its aquatic and herbal top notes feel cooling on the skin, and the cedar base provides enough substance to maintain presence without becoming heavy or cloying.'},{q:'Is Crystal Bloom suitable for formal occasions?',a:'Crystal Bloom is versatile enough for both casual and formal settings. Its clean, polished character reads as professional and composed, making it an excellent choice for office wear, daytime events, and business meetings.'}],'flora-silk':[{q:'What makes Flora Silk different from other floral perfumes?',a:'Flora Silk avoids the sweetness and powderiness common in floral fragrances. Instead, the bergamot and coffee top notes add an unexpected edge, while musk and sandalwood create a smooth, silky finish. It is floral elegance, not floral sweetness.'},{q:'Can men wear Flora Silk?',a:'While Flora Silk is designed with feminine elegance in mind, fragrance has no rules. Several of our male customers appreciate its refined character. The sandalwood and musk base adds enough depth to work beautifully on anyone.'},{q:'How should I apply Flora Silk for the best experience?',a:'Flora Silk rewards gentle application. One to two sprays on pulse points — the inner wrists and behind the ears — allow its delicate layers to unfold naturally. Avoid rubbing the wrists together, as this disrupts the top notes. On moisturised skin, Flora Silk can last the full day.'}]};function productPage(p){if(!p)return notFound();const imgSrc=p.image;const infoSrc=p.infographic||p.image.replace('.webp',' 2.webp');const gal=p.gallery||[imgSrc,infoSrc];const galAlt=[p.name+' Extrait de Parfum with box',p.name+' fragrance bottle 50ML',p.name+' fragrance notes pyramid',p.name+' — The Luxury Experience',p.name+' — The Five Vows'];const notesAccordion=p.topNotes?`<div class="notes-structured"><div class="notes-row"><span class="notes-cat">Top Notes</span><span class="notes-list">${p.topNotes.join(' · ')}</span></div><div class="notes-row"><span class="notes-cat">Heart Notes</span><span class="notes-list">${p.heartNotes.join(' · ')}</span></div><div class="notes-row"><span class="notes-cat">Base Notes</span><span class="notes-list">${p.baseNotes.join(' · ')}</span></div></div>`:`<p>${p.notes}</p>`;return `<main id="main"><div class="container product-page"><div class="product-gallery"><div class="gallery-main"><div class="gallery-track">${gal.map((src,i)=>`<div class="gallery-slide"><img src="${src}" alt="${p.name} — ${galAlt[i]||''}"${i===2?' class="pdp-infographic"':''}${i>=3?' class="pdp-text-image"':''}/></div>`).join('')}</div><button class="gallery-arrow gallery-prev" data-gallery-prev aria-label="Previous image">‹</button><button class="gallery-arrow gallery-next" data-gallery-next aria-label="Next image">›</button></div><div class="gallery-thumbs">${gal.map((src,i)=>`<button class="gallery-thumb${i===0?' active':''}" data-gallery-dot="${i}"><img src="${src}" alt="${galAlt[i]||''}"/></button>`).join('')}</div></div><div class="product-summary"><p class="crumb"><a href="/" data-link>Home</a> / <a href="/shop" data-link>Shop</a> / ${p.name}</p><h1 class="display">${p.name}</h1><p class="product-subtitle">${p.subtitle}</p><p class="pdp-character">${p.character}</p>${p.gender?'<span class="pdp-gender">'+({'Male':'For Him','Female':'For Her','Unisex':'Unisex'}[p.gender])+'</span>':''}<p class="pdp-description">${p.description}</p><div class="pdp-fragrance-profile"><span class="pdp-fp-label">Fragrance Profile</span><span class="pdp-fp-notes">${p.notes}</span></div><div class="pdp-price-block"><span class="pdp-price">₹${p.price.toLocaleString('en-IN')}</span><span class="pdp-price-tax">Inclusive of all applicable taxes</span></div><div class="purchase-row"><div class="qty"><button data-pdp-qty="-1" aria-label="Decrease quantity">−</button><span id="pdp-qty">1</span><button data-pdp-qty="1" aria-label="Increase quantity">+</button></div><button class="btn" data-add="${p.slug}" data-pdp-add>Add to Bag</button></div><div class="pdp-secondary-actions"><button data-wish="${p.slug}" class="${wishes.includes(p.slug)?'wish-active':''}">${wishes.includes(p.slug)?'♥ Saved to Wishlist':'♡ Add to Wishlist'}</button><span class="pdp-actions-divider"></span><button class="share-btn" data-share>Share</button></div><div class="pdp-delivery-note"><span>✦</span> Complimentary shipping across India</div><div class="detail-accordions"><details><summary>Fragrance Notes</summary><div class="accordion-body">${notesAccordion}</div></details><details open><summary>The Story</summary><div class="accordion-body">${p.story?p.story.map(s=>'<p>'+s+'</p>').join(''):'<p>'+p.description+'</p>'}</div></details><details><summary>Details</summary><div class="accordion-body"><p>Extrait de Parfum · 50 ML</p><p>Crafted in India with intention and care.</p></div></details><details><summary>Delivery & Returns</summary><div class="accordion-body"><p>Complimentary shipping across India. Express delivery available at checkout.</p><p>Easy returns within 7 days of delivery.</p></div></details>${(productFAQs[p.slug]||[]).length?`<details><summary>Product FAQ</summary><div class="accordion-body">${productFAQs[p.slug].map(f=>`<p><strong>${f.q}</strong></p><p>${f.a}</p>`).join('')}</div></details>`:''}</div></div></div><section class="section pdp-notes-breakdown"><div class="container"><div class="section-head"><div><p class="eyebrow">The Composition</p><h2 class="display">Fragrance Notes</h2></div></div><div class="notes-pyramid"><div class="notes-layer"><h3>Top Notes</h3><p class="notes-layer-sub">The opening impression</p><div class="notes-tags">${p.topNotes.map(n=>'<span class="note-tag">'+n+'</span>').join('')}</div></div><div class="notes-layer"><h3>Heart Notes</h3><p class="notes-layer-sub">The character of the fragrance</p><div class="notes-tags">${p.heartNotes.map(n=>'<span class="note-tag">'+n+'</span>').join('')}</div></div><div class="notes-layer"><h3>Base Notes</h3><p class="notes-layer-sub">The lasting foundation</p><div class="notes-tags">${p.baseNotes.map(n=>'<span class="note-tag">'+n+'</span>').join('')}</div></div></div></div></section>${reviewSection(p)}<section class="section pdp-also-like"><div class="container"><div class="section-head"><div><p class="eyebrow">You May Also Like</p><h2 class="display">Continue the Season.</h2></div></div><div class="product-grid">${products.filter(x=>x.slug!==p.slug).slice(0,3).map(productCard).join('')}</div></div></section><div class="pdp-sticky-bar"><span class="sticky-name">${p.name}</span><button class="btn" data-add="${p.slug}" data-pdp-add>Add to Bag</button></div></main>`}
function collection(){return `<main id="main">${pageHero('The Collection','Six Signature Fragrances.','Six expressions of one idea — luxury that stays with you.')}<div class="container"><p class="crumb"><a href="/" data-link>Home</a> / The Collection</p></div><section class="section"><div class="container intro"><div><p class="eyebrow">Six moments</p><h2 class="display">Crafted to Be Remembered.</h2></div><div class="intro-body"><p>From rain-soaked earth and royal rose to golden amber and delicate florals, every creation takes a feeling and gives it a form through fragrance.</p>${link('/shop','Explore the Collection','text-link')}</div></div></section><section class="section signature"><div class="container"><div class="product-grid">${products.map(productCard).join('')}</div></div></section></main>`}
function aboutPage(){const cms=cmsPages.about||{};const heroTitle=cms.heroTitle||'Why We Began';const heroIntro=cms.heroIntro||'As we researched fragrances and the brands people admire, our curiosity brought us closer to home. We wanted to understand Indian perfumery, and the place an Indian brand could hold in modern luxury.';const identityHeading=cms.identityHeading||'Indian at Heart.<br/>Individual in Expression.';const identityBody=cms.identityBody||'';const luxuryHeading=cms.luxuryHeading||'Our Idea of Luxury';const foundersNote=cms.foundersNote||'';return `<main id="main" class="about-v5"><section class="about-hero"><div class="v3"><p class="v3-kicker">Our Story</p><h1 class="about-hero-title">${heroTitle}</h1><p class="about-hero-intro">${heroIntro}</p></div></section><section class="about-section about-split"><div class="v3 about-split-grid"><div class="about-split-text"><p class="v3-kicker">Our Identity</p><h2>${identityHeading}</h2><p>For us, an Indian identity is not something to hide behind an unfamiliar name or a borrowed sense of prestige. It is something to express with confidence.</p><p>India is where our story begins. It is not the only reason to choose us. We want The Sixth Ritu to feel connected to India while leaving room for a contemporary, personal idea of luxury, not limited to one image, one occasion or one kind of person.</p><p>Our world draws on the things around us: the anticipation of rain, the brightness of a new morning, the warmth of an evening that passes too quickly. These become personal when someone makes a fragrance their own. A scent may remind one person of home, and another of a fresh beginning. Our role is to offer an expression. Yours is to decide what it means.</p></div><div class="about-split-img"><img src="/welcome-vertical.webp" alt="The Sixth Ritu" loading="lazy" width="1200" height="1600"/></div></div></section><section class="about-section about-ritu"><div class="v3"><p class="v3-kicker">The Name</p><h2>Why The Sixth Ritu?</h2><p class="about-ritu-intro">Ritu is the Indian word for season. A season changes more than the landscape. It changes our pace, our surroundings and sometimes the way we see ourselves.</p><div class="about-seasons-visual"><div class="about-season-list"><span>Vasanta<small>Spring</small></span><span>Grishma<small>Summer</small></span><span>Varsha<small>Monsoon</small></span><span>Sharad<small>Autumn</small></span><span>Hemanta<small>Pre-Winter</small></span><span>Shishira<small>Winter</small></span></div><div class="about-sixth"><span>The Sixth Ritu</span><p>A personal season, shaped by mood, memory and individuality rather than a date on the calendar.</p></div></div><p class="about-ritu-close">The Sixth Ritu is not about becoming someone else. It is about finding a fragrance that belongs to the way you feel.</p></div></section><section class="about-section about-luxury"><div class="v3 about-split-grid about-split-reverse"><div class="about-split-img"><img src="/hero-roses.webp" alt="Luxury craftsmanship" loading="lazy"/></div><div class="about-split-text"><p class="v3-kicker">Our Philosophy</p><h2>Our Idea of Luxury</h2><p>We believe luxury should feel considered, not complicated.</p><p>It lives in the details, without needing to announce itself: a visual identity that feels coherent, a bottle you enjoy reaching for, a wooden cap engraved with our lotus, and a fragrance that becomes part of getting ready, stepping out, or taking a moment for yourself.</p><p>Everything we make is made with love and care, from the first idea to the last detail. That is what we want you to feel when you hold a bottle for the first time.</p><p class="about-luxury-accent">The most meaningful fragrance is not necessarily the one everyone recognises. It is the one you return to because it feels right on you, until it quietly becomes yours.</p></div></div></section><section class="about-section about-collection"><div class="v3"><div class="about-collection-head"><p class="v3-kicker">The Collection</p><h2>Our First Collection</h2><p>One fragrance does not have to express everything about a person. You may love something fresh and luminous, then be drawn to something deeper and warmer. Your choice can change with the occasion, your mood, or simply your curiosity.</p><p>We are beginning with six Extrait de Parfum fragrances, and the collection will grow as our story does. Each one is a different starting point. You may find a signature to wear every day, or different scents for different moments.</p><p class="about-luxury-accent">The pleasure is in discovering what speaks to you.</p></div><div class="v3-collection-grid about-collection-grid">${products.map(p=>`<div class=\"v3-prod-card\"><div class=\"v3-prod-card-img\"><a href=\"/product/${p.slug}\" data-link><img src=\"${p.gallery?p.gallery[0]:p.image}\" alt=\"${p.name}\" loading=\"lazy\"/></a></div><h3><a href=\"/product/${p.slug}\" data-link>${p.name}</a></h3><p class=\"v3-prod-card-char\">${p.character}</p></div>`).join('')}</div>${link('/shop','Explore the Collection','v3-btn about-cta')}</div></section><section class="about-section about-founders"><div class="v3"><div class="about-founders-card"><p class="v3-kicker">A Note from the Founders</p><h2>Beginning a New Story</h2><p>We began with curiosity and a belief that an Indian fragrance brand could earn its place through its own identity.</p><p>We researched, explored and asked ourselves what we would want as customers. What would make us stop and discover a new name? What would make that first impression meaningful? And what would make us come back?</p><p>The Sixth Ritu is our answer.</p><p>We are not presenting a centuries-old family story. We are beginning a new one, with respect for where we come from and ambition for what we can create. We want you to choose our fragrances because you enjoy wearing them, and because they were made with love. We want you to see our Indian identity as a source of confidence, not a limitation.</p><p class="about-luxury-accent">That is the future we are working toward, one customer and one experience at a time.</p><div class="about-signature"><p class="about-sig-name">Mr. &amp; Mrs. Gandhi.</p><p class="about-sig-title">Founders, The Sixth Ritu</p></div></div></div></section></main>`}
function narrative(type){const content={about:['Our Story','A Season Beyond the Six','India has always known six seasons. Each transforms the world around us and leaves behind a feeling. The Sixth Ritu is the one we imagine — formed through fragrance, memory and the moments that stay with you.','Some Moments Pass. Others Become a Season of Their Own.'],ritu:['The Sixth Ritu','A season experienced through scent.','The Sixth Ritu is not a date on a calendar. It is rain after a storm, the warmth of a ritual, flowers resting on silk, or the memory of someone after they have gone.','Made to Be Worn. Created to Be Remembered.']}[type];return `<main id="main">${pageHero(content[0],content[1],content[2])}<section class="section"><div class="container info-layout"><div class="info-side">Indian imagination,<br/>contemporary fine fragrance.</div><div class="info-copy"><p class="eyebrow">Our Philosophy</p><h2>${content[3]}</h2><p>Every fragrance begins with a feeling. We translate that feeling through scent, bringing together expressive perfume ingredients and a modern approach to luxury. Each creation is designed to unfold gradually on the skin, revealing its character over time.</p><p>Like a season becoming a memory.</p></div></div></section><section class="seasons"><div class="seasons-content"><p class="eyebrow">The Inspiration</p><h2 class="display">Vasanta · Grishma<br/>Varsha · Sharad<br/>Hemanta · Shishira</h2><div class="seasons-final">THE SIXTH RITU</div><p>The Season of Luxury</p></div></section><section class="section"><div class="container"><div class="product-grid">${products.map(productCard).join('')}</div></div></section></main>`}
function contact(){return `<main id="main">${pageHero('Contact','Begin a conversation.','For enquiries, collection information or a note for our team.') }<section class="section"><div class="container contact-grid"><div><p class="eyebrow">Contact Us</p><h2 class="display" style="font-size:3rem;margin-top:0">We would love to hear from you.</h2><p>Share your details and our team will be in touch. For any questions, email us at <a href="mailto:thesixthritu@gmail.com">thesixthritu@gmail.com</a></p><div class="contact-channels"><a href="https://www.instagram.com/thesixthritu" target="_blank" rel="noopener noreferrer" class="contact-link"><span class="contact-icon">◎</span> Instagram</a><a href="https://wa.me/919157806069?text=Hello%20The%20Sixth%20Ritu%2C%20I%20would%20like%20to%20know%20more%20about%20your%20fragrances." target="_blank" rel="noopener noreferrer" class="contact-link"><span class="contact-icon">✆</span> WhatsApp</a><a href="mailto:thesixthritu@gmail.com" class="contact-link"><span class="contact-icon">✉</span> Email</a></div></div><form data-contact novalidate><div class="field"><label for="name">Name</label><input id="name" required /></div><div class="field"><label for="email">Email</label><input id="email" type="email" required /></div><div class="field"><label for="phone">Phone</label><input id="phone" type="tel" /></div><div class="field"><label for="subject">Subject</label><input id="subject" required /></div><div class="field"><label for="message">Message</label><textarea id="message" required></textarea></div><p class="form-status" aria-live="polite"></p><button class="btn">Send Message</button></form></div></section></main>`}
function searchPage(){return `<main id="main">${pageHero('Search','Find your fragrance.')}<section class="section"><div class="container search-box"><input class="search-input" data-search-input placeholder="Search the collection" aria-label="Search the collection" autofocus/><div id="search-results" class="product-grid" style="margin-top:55px"></div></div></section></main>`}
function wishlistPage(){return `<main id="main">${pageHero('Wishlist','Your saved season.')}<section class="section"><div class="container" id="wishlist-page">${wishes.length?`<div class="product-grid">${wishes.map(bySlug).filter(Boolean).map(productCard).join('')}</div>`:empty('Your wishlist is waiting.','Explore the collection','/shop')}</div></section></main>`}
function empty(title,label,path){return `<div class="empty"><h3>${title}</h3><p>Keep the fragrances that speak to you close.</p>${link(path,label,'btn')}</div>`}
function cartPage(){return `<main id="main">${pageHero('Bag','Your Season.')}<section class="section"><div class="container" id="cart-page">${cartContent(true)}</div></section></main>`}
function cartContent(full=false){if(!cart.length&&!combos.length)return `<div class="empty"><div class="empty-icon">◇</div><h3>Your bag is waiting.</h3><p>Keep the fragrances that speak to you close.</p>${link('/shop','Explore the Collection','btn')}</div>`;let rows=cart.map(i=>{let p=bySlug(i.slug);return `<div class="cart-item"><img src="${p.image}" alt="${p.name}"/><div class="cart-item-details"><h3>${p.name}</h3><p class="cart-item-variant">Extrait de Parfum \u00b7 50 ML</p><div class="qty"><button data-cart-qty="${p.slug}" data-change="-1">\u2212</button><span>${i.qty}</span><button data-cart-qty="${p.slug}" data-change="1">+</button></div></div><button class="remove" data-remove="${p.slug}">Remove</button></div>`}).join('');let comboRows=combos.map((c,idx)=>`<div class="cart-item cart-combo-item"><div class="cart-combo-badge">${c.title}</div><div class="cart-combo-products">${c.slugs.map(s=>{const p=bySlug(s);return p?`<img src="${p.image}" alt="${p.name}" title="${p.name}"/>`:''}).join('')}</div><div class="cart-item-details"><h3>${c.title} Set</h3><p class="cart-item-variant">${c.slugs.map(s=>{const p=bySlug(s);return p?p.name:s}).join(' + ')}</p><p class="combo-item-price">\u20b9${(c.price/100).toLocaleString('en-IN')} <del>\u20b9${(c.pick_count*1499).toLocaleString('en-IN')}</del></p></div><button class="remove" data-remove-combo="${idx}">Remove</button></div>`).join('');const sub=cart.reduce((a,i)=>a+bySlug(i.slug).price*i.qty,0);const cDisc=comboDiscount();const couponDisc=calcCouponDisc();const totalDisc=Math.round(cDisc/100)+couponDisc;const afterDisc=Math.max(0,sub-totalDisc);const cartSlugs=cart.map(i=>i.slug);const recs=products.filter(p=>!cartSlugs.includes(p.slug)).slice(0,2);const recsHtml=recs.length?`<div class="cart-recs"><h4>You May Also Like</h4><div class="cart-rec-grid">${recs.map(r=>`<div class="cart-rec-card"><img src="${r.image}" alt="${r.name}"/><span class="rec-name">${r.name}</span><span class="rec-type">Extrait de Parfum</span><button class="rec-add" data-add="${r.slug}">Add to Bag</button></div>`).join('')}</div></div>`:'';const _regSub=regularSubtotal();const couponHtml=(hasCombo()&&_regSub<=0)?'<div class="cart-coupon-msg">Coupon codes cannot be combined with combo offers.</div>':'<div class="cart-coupon"><input type="text" id="coupon-input" placeholder="Coupon code" value="'+coupon+'" maxlength="10"/><button id="coupon-apply">'+(coupon?'Remove':'Apply')+'</button></div>';return `${comboRows}${full?`<div style="max-width:740px">${rows}</div>`:rows}${couponHtml}<div class="cart-summary"><div class="summary-row"><span>Subtotal</span><span>\u20b9${sub.toLocaleString('en-IN')}</span></div>${cDisc?`<div class="summary-row discount"><span>Combo Savings</span><span>\u2212\u20b9${Math.round(cDisc/100).toLocaleString('en-IN')}</span></div>`:''}${couponDisc?`<div class="summary-row discount"><span>Discount (${coupon})</span><span>\u2212\u20b9${couponDisc.toLocaleString('en-IN')}</span></div>`:''}<div class="summary-row"><span>Shipping</span><span>Complimentary</span></div><div class="summary-row total"><span>You Pay</span><span>\u20b9${afterDisc.toLocaleString('en-IN')}</span></div><div class="summary-row tax-note"><span>Inclusive of all applicable taxes</span></div></div><div class="cart-actions">${link('/checkout','Proceed to Checkout','btn')}<span class="continue-link" data-close>Continue Shopping</span></div>${recsHtml}`}
function checkout(){const indianStates=['Andhra Pradesh','Arunachal Pradesh','Assam','Bihar','Chhattisgarh','Goa','Gujarat','Haryana','Himachal Pradesh','Jharkhand','Karnataka','Kerala','Madhya Pradesh','Maharashtra','Manipur','Meghalaya','Mizoram','Nagaland','Odisha','Punjab','Rajasthan','Sikkim','Tamil Nadu','Telangana','Tripura','Uttar Pradesh','Uttarakhand','West Bengal','Andaman and Nicobar Islands','Chandigarh','Dadra and Nagar Haveli and Daman and Diu','Delhi','Jammu and Kashmir','Ladakh','Lakshadweep','Puducherry'];return `<main id="main">${pageHero('Checkout','Complete your order.')}<section class="section"><div class="container tsr-checkout-grid"><form class="tsr-checkout-form" data-checkout novalidate><div class="tsr-checkout-section"><h3>Customer Details</h3><div class="tsr-field"><label>Full Name <span class="req">*</span></label><input type="text" name="fullname" required/></div><div class="tsr-field"><label>Mobile Number <span class="req">*</span></label><input type="tel" name="mobile" pattern="[0-9]{10}" maxlength="10" inputmode="numeric" required placeholder="10-digit mobile number"/></div><div class="tsr-field"><label>Email <span class="req">*</span></label><input type="email" name="email" required/></div></div><div class="tsr-checkout-section"><h3>Delivery Address</h3><div class="tsr-field"><label>Address Line 1 <span class="req">*</span></label><input type="text" name="address1" required/></div><div class="tsr-field"><label>Address Line 2</label><input type="text" name="address2"/></div><div class="tsr-field"><label>Landmark</label><input type="text" name="landmark" placeholder="Near..."/></div><div class="tsr-field-row"><div class="tsr-field"><label>City <span class="req">*</span></label><input type="text" name="city" required/></div><div class="tsr-field"><label>PIN Code <span class="req">*</span></label><input type="text" name="pin" pattern="[0-9]{6}" maxlength="6" inputmode="numeric" required placeholder="6-digit PIN"/></div></div><div class="tsr-field-row"><div class="tsr-field"><label>State <span class="req">*</span></label><select name="state" required><option value="">Select State / UT</option>${indianStates.map(s=>`<option value="${s}">${s}</option>`).join('')}</select></div><div class="tsr-field"><label>Country</label><input type="text" name="country" value="India" readonly/></div></div></div><div class="tsr-checkout-section"><h3>Payment Method</h3><div class="tsr-payment-methods"><label class="tsr-pay-option"><input type="radio" name="paymentMethod" value="prepaid" checked/><span class="tsr-pay-label"><strong>Pay Online</strong><small>UPI, Cards, Net Banking</small></span></label><label class="tsr-pay-option"><input type="radio" name="paymentMethod" value="cod"/><span class="tsr-pay-label"><strong>Cash on Delivery</strong><small>Pay when you receive</small></span></label></div></div><p class="form-status" aria-live="polite"></p><button class="btn tsr-checkout-submit">Place Order</button></form><aside class="tsr-order-summary"><h2>Order Summary</h2>${(cart.length||combos.length)?`${combos.length?'<div class="tsr-order-combos">'+combos.map(c=>'<div class="tsr-order-item tsr-order-combo"><div class="tsr-order-combo-imgs">'+c.slugs.map(s=>{const p=bySlug(s);return p?'<img src="'+p.image+'" alt="'+p.name+'"/>':''}).join('')+'</div><div><h4>'+c.title+' Set</h4><p>'+c.slugs.map(s=>{const p=bySlug(s);return p?p.name:s}).join(' + ')+'</p></div></div>').join('')+'</div>':''}<div class="tsr-order-items">${cart.map(i=>{let p=bySlug(i.slug);return `<div class="tsr-order-item"><img src="${p.image}" alt="${p.name}"/><div><h4>${p.name}</h4><p>Qty: ${i.qty}</p><p>₹${(p.price*i.qty).toLocaleString('en-IN')}</p></div></div>`}).join('')}</div><div class="cart-summary"><div class="summary-row"><span>Subtotal</span><span>\u20b9${(function(){const s=cart.reduce((a,i)=>a+bySlug(i.slug).price*i.qty,0);return s.toLocaleString('en-IN')})()}</span></div>${comboDiscount()?'<div class="summary-row discount"><span>Combo Savings</span><span>\u2212\u20b9'+Math.round(comboDiscount()/100).toLocaleString('en-IN')+'</span></div>':''}${(coupon&&calcCouponDisc()>0)?'<div class="summary-row discount"><span>Discount ('+coupon+')</span><span>\u2212\u20b9'+calcCouponDisc().toLocaleString('en-IN')+'</span></div>':''}<div class="summary-row"><span>Shipping</span><span>Complimentary</span></div><div class="summary-row total"><span>You Pay</span><span>\u20b9${Math.max(0,cart.reduce((a,i)=>a+bySlug(i.slug).price*i.qty,0)-Math.round(comboDiscount()/100)-calcCouponDisc()).toLocaleString('en-IN')}</span></div><div class="summary-row tax-note"><span>Inclusive of all applicable taxes</span></div></div>`:'<p class="tsr-empty-cart">Your bag is empty. Add a fragrance before continuing.</p>'}<p class="form-note">Your order will be processed securely. Free shipping on all orders.</p></aside></div></section></main>`}
function account(){return `<main id="main">${pageHero('Account','Your Sixth Ritu.')}<section class="section"><div class="container"><div class="account-card"><h2 class="display" style="font-size:3rem;margin-top:0">Welcome.</h2><p>Sign-in and order history will be connected when the customer account service is ready.</p>${link('/account/orders','View order history','text-link')}</div></div></section></main>`}
function supportPage(title,copy){return `<main id="main">${pageHero('Customer Care',title,'')}<section class="section"><div class="container"><div class="policy-content">${copy}</div></div></section></main>`}
const _policies={privacy:{title:'Privacy Policy',content:'<p class="policy-date">Last updated: November 2026</p><p>This Privacy Policy describes how The Sixth Ritu (“we”, “us”, or “the Site”) collects, uses, and discloses your Personal Information when you visit or make a purchase from <a href="https://thesixthritu.in">thesixthritu.in</a>.</p><p>We value and appreciate the trust you place in The Sixth Ritu. Hence, we insist upon the highest standards for the security of your personal information. Please read the following statement to learn about our information gathering and dissemination practices.</p><p>Our Privacy Policy is subject to change at any time without notice. To stay informed, please review this policy periodically.</p><h3>Collecting Personal Information</h3><p>When you visit the Site, we collect certain information about your device, your interaction with the Site, and information necessary to process your purchases. We may also collect additional information if you contact us for customer support.</p><h4>Device Information</h4><p><strong>Examples:</strong> Version of web browser, IP address, time zone, cookie information, pages or products you view, search terms, and how you interact with the Site.</p><p><strong>Purpose:</strong> To load the Site accurately for you, and to perform analytics on Site usage to optimise our Site.</p><p><strong>Source:</strong> Collected automatically when you access our Site using cookies, log files, web beacons, tags, or pixels.</p><h4>Order Information</h4><p><strong>Examples:</strong> Name, billing address, shipping address, email address, and phone number.</p><p><strong>Purpose:</strong> To provide products or services to you, fulfil our contract, process your payment, arrange for shipping, provide you with invoices and order confirmations, communicate with you, screen orders for potential risk or fraud, and — in line with your preferences — provide you with information relating to our products or services.</p><p><strong>Source:</strong> Collected from you.</p><p><strong>Note:</strong> Payment card details are processed securely by our payment provider, Razorpay. We do not store your complete credit or debit card numbers on our servers.</p><h4>Lead Information</h4><p>If you subscribe to our welcome offer or newsletter, we collect your name, phone number, and date of birth (optional). This information may be synchronised with our internal records for communication purposes.</p><h3>Sharing Personal Information</h3><p>We may share your Personal Information to comply with applicable laws and regulations, to respond to a subpoena, search warrant or other lawful request for information we receive, or to otherwise protect our rights.</p><h3>Using Personal Information</h3><p>The Sixth Ritu uses your Personal Information to provide our services to you, which includes: processing payments via Razorpay, shipping and fulfilment of your order, and any actions legally required.</p><h3>Security Precautions</h3><p>Our Site has stringent security measures in place to protect the loss, misuse, and alteration of information under our control. Whenever you access your account information, we offer the use of a secure server. Once your information is in our possession, we adhere to strict security guidelines, protecting it against unauthorised access.</p><h3>Cookies</h3><p>A cookie is a small amount of information downloaded to your computer or device when you visit our Site. We use functional and performance cookies to make your browsing experience better by allowing the website to remember your actions and preferences (such as login and region selection). This means you don’t have to re-enter this information each time you return to the site or browse between pages.</p><h3>Changes</h3><p>We may update this Privacy Policy from time to time to reflect changes to our practices or for other operational, legal, or regulatory reasons.</p><h3>Contact</h3><p>For any questions regarding this policy, please reach us at <a href="mailto:thesixthritu@gmail.com">thesixthritu@gmail.com</a>.</p>'},shipping:{title:'Shipping Policy',content:'<p class="policy-date">Last updated: November 2026</p><p>Our standard delivery timeline across India is <strong>7–10 business days</strong>.</p><p>While we make every effort to ensure that your order reaches you within the stated timeframe, please bear in mind that delivery may occasionally take longer due to circumstances beyond our control, including:</p><ul><li>Adverse weather conditions</li><li>Transportation or logistical delays</li><li>Political disruptions or local restrictions</li><li>Other unforeseen circumstances affecting delivery services</li></ul><p>Such delays are outside the control of The Sixth Ritu and may result in an extension of the estimated delivery timeline. While we will make every reasonable effort to assist you with your order and provide relevant delivery updates, The Sixth Ritu cannot be held liable or provide compensation for delays arising from circumstances beyond our control.</p><p>For any shipping enquiries, please contact us at <a href="mailto:thesixthritu@gmail.com">thesixthritu@gmail.com</a>.</p>'},refund:{title:'Refund Policy',content:'<p class="policy-date">Last updated: November 2026</p><p>We do not offer returns or exchanges, as each fragrance is presented in its intended, complete form.</p><p>If your experience with the fragrance feels unexpected, you may write to us at <a href="mailto:thesixthritu@gmail.com">thesixthritu@gmail.com</a>. We will review each note with care.</p><p>In the unlikely event that your order arrives damaged, we request that the unsealing of the package be recorded. This allows us to assess and resolve the matter promptly.</p><p class="policy-note"><em>This policy does not override any mandatory consumer rights available to you under applicable Indian law.</em></p>'},terms:{title:'Terms & Conditions',content:'<p class="policy-date">Last updated: November 2026</p><h3>Terms of Use</h3><p>All information, products and services displayed on the Site constitute an “invitation to offer”. Your order for purchase constitutes your “offer” which shall be subject to the terms and conditions as listed below. The Sixth Ritu has the right to accept or reject your offer without assigning any reason thereof.</p><p>By subscribing to or using any of our services you agree that you have read, understood and are bound by the Terms, regardless of how you subscribe to or use the services. If you do not want to be bound by the Terms, you must not subscribe to or use our services.</p><p>We reserve the right to add, delete, alter or modify these terms and conditions at any time. You are therefore advised to read carefully these terms and conditions every time you use the website of The Sixth Ritu.</p><h3>Liability</h3><p>We will not be responsible for any damage suffered by users from use of the services on our website. This without limitation includes loss of revenue or data resulting from delays, non-deliveries, missed deliveries, or service interruptions as may occur because of any act or omission of the vendor. This disclaimer of liability also applies to any damages or injury caused by any failure of performance, negligence, defect, deletion, error, omission, interruption, delay in operation or transmission, computer virus, communication line failure, theft or destruction or unauthorised access to, alteration of, or use of record, whether for breach of contract, tortuous behaviour, or under any other cause of action.</p><h3>Fraudulent Orders</h3><p>To provide a safe and secure shopping experience, we regularly scan for fraudulent transactions and suspicious activity. We reserve the right to cancel all past, pending and future orders without any liability.</p><h3>Pricing &amp; Availability</h3><p>The prices and availability of products are subject to change without prior notice at our sole discretion.</p><h3>Cancellation of Orders</h3><p>We reserve the right to refuse or cancel any order placed for a product that is listed at an incorrect price or for any other reason. This shall be regardless of whether the order has been confirmed and/or payment has been received. The payment shall be refunded and the user shall be informed of the same.</p><p>If a non-delivery or late delivery occurs due to a mistake by the user (e.g. wrong or incomplete name or address, or recipient not available), any extra cost spent by us for re-delivery shall be claimed from the user placing the order.</p><h3>Customer Information</h3><p>The user agrees to give accurate, authentic and true information. We reserve the right to confirm and validate the information and other details provided by the user at any point of time. If any such user details are found not to be true wholly or partly, we have the right in our sole discretion to reject the registration and debar the user from using the services of <a href="https://thesixthritu.in">thesixthritu.in</a> without prior intimation whatsoever.</p><h3>Payment</h3><p>All payments are processed securely through Razorpay. We do not store your complete card details. Any disputes related to payment transactions should be reported to us and your card-issuing bank.</p><h3>Applicable Law</h3><p>This agreement shall be construed in accordance with the applicable laws of India.</p><p>For any questions regarding these terms, please contact us at <a href="mailto:thesixthritu@gmail.com">thesixthritu@gmail.com</a>.</p>'}};
function policyPage(slug){const p=_policies[slug];if(!p)return notFound();return `<main id="main">${pageHero('Legal',p.title,'')}<section class="section"><div class="container"><div class="policy-content">${p.content}</div></div></section></main>`}
function comboSection(){if(!activeOffers.length)return '';return `<section class="combo-section section"><div class="container"><div class="combo-head"><p class="eyebrow">Limited-Time Offer</p><h2 class="display">Build Your Fragrance Set</h2><p class="combo-sub">Choose your favourites and save. Available 4–14 November only.</p></div><div class="combo-offers-grid">${activeOffers.filter(o=>o.type==='combo').map(o=>{const save=(o.pick_count*149900-o.combo_price)/100;return `<div class="combo-card"><div class="combo-card-badge">SAVE ₹${save.toLocaleString('en-IN')}</div><h3>${o.title}</h3><p class="combo-card-desc">${o.description}</p><div class="combo-card-price"><span class="combo-old">₹${(o.pick_count*1499).toLocaleString('en-IN')}</span><span class="combo-new">₹${(o.combo_price/100).toLocaleString('en-IN')}</span></div><button class="btn" data-build-combo="${o.id}">Choose ${o.pick_count} Fragrances</button></div>`}).join('')}</div></div></section>`}
function instagramSection(){return `<section class="v3-instagram v3-sec" id="tsr-instagram"><div class="v3"><div class="v3-instagram-head v3-sr"><p class="v3-kicker">FOLLOW OUR JOURNEY</p><h2 class="v3-heading">Moments of luxury, captured on Instagram.</h2></div><div class="v3-elfsight-wrap"><div class="elfsight-app-6c68116f-fc57-4d1f-97b6-59eb9b554f10" data-elfsight-app-lazy></div></div><div class="v3-instagram-cta v3-sr"><a href="https://www.instagram.com/thesixthritu/" target="_blank" rel="noopener noreferrer" class="v3-btn v3-btn-ig"><svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="1.5"><rect x="2" y="2" width="20" height="20" rx="5"/><circle cx="12" cy="12" r="5"/><circle cx="17.5" cy="6.5" r="1.5" fill="currentColor" stroke="none"/></svg> Follow Us on Instagram</a></div></div></section>`}
function loadInstagramFeed(){const el=document.getElementById('tsr-instagram');if(!el)return;if(document.querySelector('script[src*="elfsightcdn"]')){try{window.eapps&&eapps.Platform&&eapps.Platform.init()}catch(e){}return}const io=new IntersectionObserver((entries,obs)=>{if(entries[0].isIntersecting){obs.disconnect();const s=document.createElement('script');s.src='https://elfsightcdn.com/platform.js';s.async=true;document.head.appendChild(s)}},{rootMargin:'200px'});io.observe(el)}
function comboBuilder(offerId){const o=activeOffers.find(x=>x.id===offerId);if(!o)return;const eligible=o.eligible_products||[];const modal=document.createElement('div');modal.className='combo-modal-overlay';modal.innerHTML=`<div class="combo-modal"><button class="combo-modal-close" data-combo-close>&times;</button><div class="combo-modal-header"><p class="eyebrow">Build Your Set</p><h2>${o.title}</h2><p>Select ${o.pick_count} fragrances below</p><div class="combo-modal-price">Set Price: <strong>₹${(o.combo_price/100).toLocaleString('en-IN')}</strong> <del>₹${(o.pick_count*1499).toLocaleString('en-IN')}</del></div></div><div class="combo-modal-grid">${eligible.map(slug=>{const p=bySlug(slug);if(!p)return '';return `<div class="combo-pick" data-combo-slug="${slug}"><img src="${p.image}" alt="${p.name}"/><h4>${p.name}</h4><p>${p.character}</p><div class="combo-pick-check">✓</div></div>`}).join('')}</div><div class="combo-modal-footer"><span class="combo-selected-count">0 / ${o.pick_count} selected</span><button class="btn combo-add-btn" disabled>Add Set to Bag</button></div></div>`;document.body.appendChild(modal);requestAnimationFrame(()=>requestAnimationFrame(()=>modal.classList.add('open')));const selected=[];const updateUI=()=>{modal.querySelectorAll('.combo-pick').forEach(el=>{el.classList.toggle('active',selected.includes(el.dataset.comboSlug))});modal.querySelector('.combo-selected-count').textContent=`${selected.length} / ${o.pick_count} selected`;const btn=modal.querySelector('.combo-add-btn');btn.disabled=selected.length!==o.pick_count;btn.textContent=selected.length===o.pick_count?'Add Set to Bag — ₹'+(o.combo_price/100).toLocaleString('en-IN'):'Select '+(o.pick_count-selected.length)+' more'};const close=()=>{modal.classList.remove('open');setTimeout(()=>modal.remove(),300)};modal.querySelector('[data-combo-close]').onclick=close;modal.addEventListener('click',e=>{if(e.target===modal)close()});modal.querySelectorAll('.combo-pick').forEach(el=>{el.onclick=()=>{const slug=el.dataset.comboSlug;const idx=selected.indexOf(slug);if(idx>=0)selected.splice(idx,1);else if(selected.length<o.pick_count)selected.push(slug);updateUI()}});modal.querySelector('.combo-add-btn').onclick=()=>{if(selected.length!==o.pick_count)return;const comboItem={offerId:o.id,title:o.title,slugs:[...selected],price:o.combo_price,pick_count:o.pick_count};combos.push(comboItem);selected.forEach(slug=>{const existing=cart.find(i=>i.slug===slug);if(!existing)cart.push({slug,qty:1});else existing.qty+=1});persist();close();render();toast(o.title+' set added to bag!');openCart()}}
function removeCombo(idx){const c=combos[idx];if(c){c.slugs.forEach(slug=>{const ci=cart.find(i=>i.slug===slug);if(ci){ci.qty-=1;if(ci.qty<1)cart=cart.filter(i=>i.slug!==slug)}});combos.splice(idx,1);persist();render()}}
function comboCartTotal(){return combos.reduce((a,c)=>a+c.price,0)}
function comboFullPrice(){return combos.reduce((a,c)=>a+c.slugs.length*149900,0)}
function comboDiscount(){return comboFullPrice()-comboCartTotal()}
function hasCombo(){return combos.length>0}
function faq(){return `<main id="main">${pageHero('Customer Care','Frequently Asked Questions.')}<section class="section"><div class="container"><div class="faq-grid"><div class="faq-category"><h3>Shopping & Orders</h3><div class="detail-accordions"><details open><summary>How can I choose a fragrance?</summary><p>Begin with the mood that feels closest to you. Our <a href="/shop" data-link>Shop</a> page lets you explore by character, or use the Mood Finder on our homepage to discover which Ritu suits you today.</p></details><details><summary>What concentration are your fragrances?</summary><p>All six fragrances are Extrait de Parfum (50 ML) \u2014 the highest concentration, offering exceptional longevity and depth that lasts throughout the day.</p></details><details><summary>How do I place an order?</summary><p>Browse our collection, add your chosen fragrances to the bag, and proceed to checkout. We accept all major payment methods and offer complimentary shipping across India.</p></details><details><summary>Can I use a discount code?</summary><p>Yes! Enter your coupon code in the cart drawer before checkout. New customers receive an exclusive welcome code upon signing up.</p></details></div></div><div class="faq-category"><h3>Shipping & Returns</h3><div class="detail-accordions"><details><summary>Do you offer free shipping?</summary><p>Yes, complimentary shipping is available on all orders across India. Express delivery options are available at checkout.</p></details><details><summary>How long does delivery take?</summary><p>Delivery details will be shared once your order is processed.</p></details><details><summary>What is your return policy?</summary><p>We offer easy returns within 7 days of delivery. The product must be unused and in its original packaging. Please contact our team to initiate a return.</p></details><details><summary>Do you ship internationally?</summary><p>Currently, we ship across India only. International shipping will be announced soon. Follow us for updates.</p></details></div></div><div class="faq-category"><h3>Product & Care</h3><div class="detail-accordions"><details><summary>How should I store my fragrance?</summary><p>Keep your fragrance away from direct sunlight and extreme temperatures. Store upright in a cool, dry place to preserve the character of the scent.</p></details><details><summary>How long does the fragrance last?</summary><p>As Extrait de Parfum, our fragrances offer 8\u201312 hours of wear. Longevity varies by skin type, climate, and application.</p></details><details><summary>Are your fragrances cruelty-free?</summary><p>Absolutely. None of our fragrances are tested on animals. We are committed to ethical and responsible beauty.</p></details><details><summary>Are the prices inclusive of tax?</summary><p>Yes, all prices displayed are inclusive of all applicable taxes. The price you see is the price you pay.</p></details></div></div><div class="faq-category"><h3>About The Sixth Ritu</h3><div class="detail-accordions"><details><summary>What does \u201cThe Sixth Ritu\u201d mean?</summary><p>India has always known six seasons \u2014 Vasanta, Grishma, Varsha, Sharad, Hemanta, and Shishira. We imagine a seventh: a season experienced through scent, emotion, and memory.</p></details><details><summary>Where are your fragrances made?</summary><p>All our fragrances are crafted in India, blending fine Indian botanicals with precious global ingredients.</p></details><details><summary>How can I contact the team?</summary><p>Use the <a href="/contact" data-link>contact form</a> and our team will respond promptly. You can also reach us at our social channels @TheSixthRitu.</p></details></div></div><div class="faq-category"><h3>Fragrance Education</h3><div class="detail-accordions"><details><summary>What are top, heart, and base notes?</summary><p>Fragrances unfold in three layers. Top notes are the bright, initial impression lasting 15–30 minutes. Heart notes form the core character, emerging as the top fades. Base notes are the deep, long-lasting foundation that lingers for hours. Together they create the perfume pyramid.</p></details><details><summary>What fragrance families exist?</summary><p>The major families are floral (rose, jasmine), oriental/amber (vanilla, spice), woody (sandalwood, cedar, oud), fresh (citrus, aquatic), and gourmand (coffee, vanilla, honey). Most fine fragrances blend elements from multiple families for complexity.</p></details><details><summary>What is the difference between EDT, EDP, and Extrait de Parfum?</summary><p>Eau de Toilette (EDT) contains 5–15% fragrance oils and lasts 3–5 hours. Eau de Parfum (EDP) holds 15–20% and lasts 6–8 hours. Extrait de Parfum, used by The Sixth Ritu, contains 20–40% — the highest concentration, delivering 8–12 hours of rich, nuanced wear.</p></details><details><summary>Why does the same perfume smell different on different people?</summary><p>Your skin’s natural pH, moisture level, temperature, and microbiome all interact with fragrance molecules, causing them to develop uniquely. Diet, medication, and even stress can subtly influence scent. This is why testing on your own skin is essential before choosing a fragrance.</p></details></div></div><div class="faq-category"><h3>Gifting & Occasions</h3><div class="detail-accordions"><details><summary>Which fragrance makes the best gift?</summary><p>Consider the recipient’s personality: <a href="/product/dark-monsoon" data-link>Dark Monsoon</a> for the bold and commanding, <a href="/product/royal-zafran-rose" data-link>Royal Zafran Rose</a> for the elegant and regal, <a href="/product/golden-ritual" data-link>Golden Ritual</a> for the warm and comforting. Our <a href="/fragrance-guide" data-link>Fragrance Guide</a> can help you decide.</p></details><details><summary>What occasions suit luxury perfume as a gift?</summary><p>Luxury fragrance is perfect for birthdays, anniversaries, weddings, festive celebrations like Diwali and Eid, housewarmings, and thank-you gestures. Every Sixth Ritu fragrance arrives in luxury packaging designed to feel like an occasion itself.</p></details><details><summary>Do you offer sample sizes or discovery sets?</summary><p>Currently, our fragrances are available in the full 50 ML Extrait de Parfum size. Follow us on social media for announcements about future discovery offerings.</p></details></div></div></div></div></section></main>`}
function fragranceGuide(){const compTable=products.map(p=>`<tr><td><a href="/product/${p.slug}" data-link>${p.name}</a></td><td>${p.character}</td><td>${({'Male':'For Him','Female':'For Her','Unisex':'Unisex'}[p.gender])||''}</td><td>${p.notes}</td><td>${p.mood}</td></tr>`).join('');return `<main id="main">${pageHero('Fragrance Guide','Your Guide to Luxury Fragrance.','Everything you need to understand, choose, and wear fine perfume.')}<section class="section"><div class="container journal-article"><p class="crumb"><a href="/" data-link>Home</a> / Fragrance Guide</p><div class="journal-block"><h2>Understanding Fragrance Notes</h2><p>Every fine fragrance unfolds in three acts. <strong>Top notes</strong> are the opening impression — bright, fleeting molecules like citrus, herbs, and light florals that greet you in the first 15–30 minutes. <strong>Heart notes</strong> form the core character, emerging as the top fades — rose, jasmine, spices, and woods that define the fragrance’s personality. <strong>Base notes</strong> are the foundation — deep, long-lasting ingredients like oud, musk, amber, sandalwood, and vanilla that anchor the composition and linger for hours.</p><p>When trying a new fragrance, resist judging it on the first spray alone. Give it at least 30 minutes on your skin to let the heart notes emerge, and two hours to experience the full drydown. The base notes are where you discover the fragrance’s true character.</p></div><div class="journal-block"><h2>Fragrance Concentrations</h2><p>The concentration of aromatic oils determines a fragrance’s intensity and longevity:</p><p><strong>Eau de Cologne (EDC)</strong> — 2–4% oils. Light and refreshing, lasts 1–2 hours. Best for a quick refresh.</p><p><strong>Eau de Toilette (EDT)</strong> — 5–15% oils. Moderate presence, lasts 3–5 hours. A common everyday choice.</p><p><strong>Eau de Parfum (EDP)</strong> — 15–20% oils. Rich and lasting, 6–8 hours of wear. The standard for luxury fragrance.</p><p><strong>Extrait de Parfum</strong> — 20–40% oils. The highest concentration available. Delivers the richest expression with 8–12 hours of wear. Every fragrance in The Sixth Ritu collection is an Extrait de Parfum.</p></div><div class="journal-block"><h2>How to Apply Perfume</h2><p>Apply fragrance to clean, moisturised skin immediately after a shower. Target <strong>pulse points</strong> where blood vessels sit close to the surface — the inner wrists, behind the ears, the base of the throat, and the inner elbows. These areas generate warmth that helps the fragrance project and evolve.</p><p>Avoid rubbing your wrists together after application — this crushes the delicate top notes and accelerates the transition to base notes. Instead, let the fragrance dry naturally. For Extrait de Parfum, one to two sprays is usually sufficient due to the high concentration.</p></div><div class="journal-block"><h2>Storing Your Fragrance</h2><p>Keep bottles in a cool, dry place away from direct sunlight and temperature fluctuations. A bedroom drawer or wardrobe shelf is ideal. Avoid the bathroom, where humidity and heat from showers degrade the oils over time. The original box provides additional light protection. A well-stored Extrait de Parfum maintains its character for three to five years or longer.</p></div><div class="journal-block"><h2>Find Your Mood Match</h2><p>Each of our six fragrances captures a distinct mood. Explore the one that speaks to you:</p><div class="product-grid">${products.map(productCard).join('')}</div></div><div class="journal-block"><h2>The Collection at a Glance</h2><p style="font-size:.8rem;color:#a27d4e;text-align:right;margin:0 0 4px" class="scroll-hint">Scroll to see all columns →</p><div style="overflow-x:auto;-webkit-overflow-scrolling:touch;border:1px solid rgba(162,125,78,.1);border-radius:4px"><table class="guide-table" style="min-width:600px;width:100%;border-collapse:collapse;margin:0;font-size:.95rem"><thead><tr style="border-bottom:2px solid rgba(162,125,78,.2)"><th style="text-align:left;padding:12px 8px">Fragrance</th><th style="text-align:left;padding:12px 8px">Character</th><th style="text-align:left;padding:12px 8px">Gender</th><th style="text-align:left;padding:12px 8px">Key Notes</th><th style="text-align:left;padding:12px 8px">Mood</th></tr></thead><tbody style="vertical-align:top">${compTable}</tbody></table></div></div><div class="journal-nav">${link('/shop','Shop the Collection →','text-link')} ${link('/journal','Read the Journal →','text-link')}</div></div></section></main>`}
const journalArticles=[{slug:'art-of-indian-perfumery',tag:'Craft',title:'The Art of Indian Perfumery',hero:'/hero banner 2.webp',intro:'How ancient techniques meet modern luxury in every bottle.',body:[{h:'A Heritage of Scent',p:'India has been a land of fragrance for millennia. From the attars of Kannauj to the sacred incense of temples, scent has always been woven into the fabric of Indian life. The art of perfumery here is not merely a craft \u2014 it is a tradition that connects the earthly to the divine.'},{h:'From Earth to Essence',p:'The finest Indian perfumery begins with the raw material \u2014 sandalwood from Mysore, vetiver from Rajasthan, jasmine from Madurai. Each ingredient carries the character of its origin, the soil, the climate, the hands that harvested it.'},{h:'Modern Expression',p:'At The Sixth Ritu, we honour this heritage while embracing contemporary perfumery techniques. Our fragrances are composed with the precision of modern science and the soul of ancient tradition, creating something that feels both timeless and entirely new.'},{h:'The Extrait Difference',p:'We chose Extrait de Parfum \u2014 the highest concentration \u2014 because a fragrance meant to be remembered deserves to last. Our compositions unfold over hours, revealing layers of character that evolve with the wearer.'}]},{slug:'creating-your-fragrance-ritual',tag:'Ritual',title:'Creating Your Fragrance Ritual',hero:'/hero banner 3.webp',intro:'Transform an everyday moment into something extraordinary.',body:[{h:'The Morning Ritual',p:'A fragrance ritual begins with intention. Before dressing, before the world demands your attention, take a moment. Hold the bottle. Let the cap release the first whisper of scent. This is your moment.'},{h:'Where to Apply',p:'Pulse points are where your fragrance speaks loudest \u2014 the wrists, behind the ears, the base of the throat. But the true secret is to spray where you want to be discovered: the nape of the neck, the inner elbow, the décolletage.'},{h:'Layering & Longevity',p:'For the richest experience, apply to moisturised skin. Fragrance clings to hydration. Some prefer a single scent; others layer two complementary fragrances \u2014 Dark Monsoon with Golden Ritual creates something deeply personal and utterly unique.'},{h:'Making It Yours',p:'A fragrance ritual is not about following rules. It is about creating a moment that belongs only to you. The spray that signals the beginning of an evening. The scent that accompanies every important meeting. The fragrance that becomes your signature.'}]},{slug:'why-india-has-six-seasons',tag:'Season',title:'Why India Has Six Seasons',hero:'/hero banner 4.webp',intro:'The ancient wisdom behind the Sixth Ritu philosophy.',body:[{h:'Beyond Four Seasons',p:'While much of the world divides the year into four seasons, Indian tradition recognises six \u2014 each one a distinct chapter in the story of the year, each carrying its own mood, its own palette, its own fragrance.'},{h:'The Six Ritus',p:'Vasanta (Spring) brings new beginnings. Grishma (Summer) blazes with radiance. Varsha (Monsoon) washes the earth clean. Sharad (Autumn) brings clarity. Hemanta (Pre-Winter) wraps the world in golden warmth. Shishira (Winter) holds everything in rich stillness.'},{h:'The Unnamed Season',p:'But there is a seventh experience \u2014 one the ancient texts never codified. It lives between moments. In the trace of a fragrance on a letter. In the warmth of a memory triggered by a scent. In the feeling that remains long after the moment has passed.'},{h:'Becoming The Sixth Ritu',p:'This unnamed season became the inspiration for everything we create. Each of our six fragrances captures a different expression of this idea \u2014 that the most profound experiences are not bound by time or calendar, but by emotion and memory.'}]},{slug:'the-science-of-scent',tag:'Science',title:'The Science of Scent',hero:'/hero-roses.webp',intro:'How fragrance works — from the perfume pyramid to the way notes evolve on your skin.',body:[{h:'The Perfume Pyramid',p:'Every fine fragrance is built on a three-tier structure known as the perfume pyramid. The top notes are the first impression — bright, volatile molecules that greet you in the opening minutes. The heart notes emerge as the top fades, forming the core character of the fragrance. Finally, the base notes anchor everything, lingering for hours and giving a scent its lasting signature. At The Sixth Ritu, each fragrance is composed so that these three layers unfold gradually, rewarding the wearer with new facets over time.'},{h:'How Notes Evolve on Skin',p:'Fragrance does not remain static after application. Your skin’s natural warmth and pH interact with the perfume oils, causing lighter molecules to evaporate first and heavier ones to emerge later. This is why a fragrance smells different on paper than on your wrist, and why two people wearing the same perfume can smell quite different. Factors like hydration, body temperature, and even diet can subtly influence how a scent develops throughout the day.'},{h:'Concentration Matters',p:'The concentration of aromatic compounds determines both intensity and longevity. Eau de Cologne (EDC) contains roughly 2–4% perfume oils and lasts 1–2 hours. Eau de Toilette (EDT) holds 5–15% and lasts 3–5 hours. Eau de Parfum (EDP) carries 15–20% for 6–8 hours of wear. Extrait de Parfum, the concentration used by The Sixth Ritu, contains 20–40% perfume oils, delivering the richest expression and longest wear — typically 8–12 hours.'},{h:'Skin Chemistry and Scent',p:'Your skin is not a passive canvas. Its microbiome, moisture level, and natural oils all affect how fragrance molecules behave. Well-moisturised skin holds scent longer because oils slow evaporation. Pulse points — wrists, neck, behind the ears — generate warmth that helps project the fragrance. Understanding your own skin chemistry is the first step toward finding a scent that feels uniquely yours.'},{h:'Why Extrait de Parfum',p:'We chose Extrait de Parfum for every fragrance in our collection because luxury deserves longevity. At the highest concentration, the notes have room to express themselves fully — the opening is richer, the heart is more nuanced, and the base lasts well into the next day. Whether it is the deep oud of Dark Monsoon or the delicate florals of Flora Silk, the Extrait concentration ensures each fragrance tells its complete story.'}]},{slug:'how-to-choose-your-signature-scent',tag:'Guide',title:'How to Choose Your Signature Scent',hero:'/hero banner 2.webp',intro:'A practical guide to finding the fragrance that feels like you.',body:[{h:'Start with Mood, Not Marketing',p:'The most reliable way to choose a fragrance is to begin with how you want to feel. Forget trends and celebrity endorsements — a signature scent should reflect your inner world. Do you gravitate toward calm and comfort? Golden Ritual, with its warm tea and vanilla character, might speak to you. Do you prefer to feel bold and commanding? Dark Monsoon’s deep oud and amber could be your match. Trust your instincts over descriptions.'},{h:'Consider the Occasion',p:'Different moments call for different fragrances. A fresh, airy scent like Crystal Bloom works beautifully for daytime and professional settings, while something richer like Royal Zafran Rose comes alive at evening gatherings and celebrations. Some people keep one signature scent for all occasions; others curate a small wardrobe of two or three. There is no wrong approach — only what feels right to you.'},{h:'Season and Climate',p:'India’s diverse climate plays a significant role in how fragrance performs. In warm, humid weather, lighter compositions project more naturally — Crystal Bloom and Flora Silk are well suited to summer. During cooler months, the warmth of your skin draws out the deeper notes in fragrances like Golden Leaf and Dark Monsoon. Pay attention to how a scent evolves in different weather — it will tell you when it is at its best.'},{h:'Test on Skin, Not Paper',p:'Paper strips give you a first impression, but skin is where a fragrance truly reveals itself. Apply to your wrist and wait at least 30 minutes before deciding. The top notes will give way to the heart, and the character of the fragrance will shift. Revisit it after two hours to experience the base notes. A fragrance you are indifferent to at first spray might become captivating by the drydown.'},{h:'Let It Find You',p:'A signature scent often chooses you as much as you choose it. It is the one you keep reaching for, the one that feels like a second skin. If people begin to associate a certain scent with your presence, you have found your signature. At The Sixth Ritu, each of our six fragrances is designed to be someone’s signature — the question is simply which season speaks to you.'}]},{slug:'understanding-fragrance-families',tag:'Education',title:'Understanding Fragrance Families',hero:'/hero banner 3.webp',intro:'From floral to woody — a guide to the major scent families and where our fragrances fit.',body:[{h:'What Are Fragrance Families?',p:'Fragrance families are categories that group perfumes by their dominant characteristics. Understanding them helps you identify what you naturally gravitate toward and explore related scents with confidence. The major families include floral, oriental (amber), woody, fresh, and gourmand. Most fine fragrances blend elements from multiple families, creating complexity that defies simple labels — but knowing the families gives you a useful starting point.'},{h:'Floral: The Garden in a Bottle',p:'The floral family is built around flower notes — rose, jasmine, lily, tuberose, and more. These fragrances range from light and dewy to rich and opulent. Flora Silk belongs here, with its graceful bouquet of bergamot, rose, and jasmine softened by musk and sandalwood. Royal Zafran Rose also draws deeply from this family, pairing rose with saffron and musk for something regal and complex.'},{h:'Oriental and Woody: Depth and Warmth',p:'Oriental fragrances feature warm, rich ingredients like amber, vanilla, and spices. Woody compositions lean on sandalwood, cedar, oud, and vetiver. Dark Monsoon bridges both worlds with its combination of amber, agar wood oil, and suede, creating something powerful and grounding. Golden Leaf, with its agarwood and tonka bean base, also lives in this space — warm, confident, and refined.'},{h:'Fresh: Clean and Luminous',p:'Fresh fragrances evoke water, green leaves, citrus, and aromatic herbs. They feel clean and energising, ideal for daytime and warm weather. Crystal Bloom is The Sixth Ritu’s expression of this family — sea water, lavender, and rosemary opening into jasmine and cedar. It captures the feeling of morning light on still water.'},{h:'Gourmand: Comfort in a Bottle',p:'Gourmand fragrances feature edible-inspired notes like vanilla, coffee, chocolate, caramel, and honey. Golden Ritual embodies this family beautifully — its tea, jasmine, and vanilla composition creates warmth without heaviness. These are comfort fragrances, perfect for intimate moments and cooler days when you want to feel enveloped in something familiar and soothing.'}]},{slug:'history-of-attar-in-india',tag:'Heritage',title:'The History of Attar in India',hero:'/hero banner 4.webp',intro:'From the workshops of Kannauj to the courts of emperors — India’s ancient fragrance tradition.',body:[{h:'Kannauj: The Perfume Capital',p:'The city of Kannauj in Uttar Pradesh has been the heart of Indian perfumery for centuries. Known as the ‘Perfume Capital of India,’ Kannauj is home to generations of attar makers who practise their craft in small, family-run workshops called bhattis. The city’s association with fragrance is documented in historical texts and travellers’ accounts spanning several hundred years, making it one of the oldest continuous centres of perfume production in the world.'},{h:'The Degchi Process',p:'Traditional Indian attar is made through hydro-distillation using copper vessels called degchis. Flowers, herbs, or wood are placed with water in the degchi and heated over a low fire. The steam carrying the aromatic compounds passes through a bamboo pipe into a receiving vessel called a bhapka, which sits in a cooling tank. The essential oil gradually separates and is collected into a base of sandalwood oil. This patient, time-intensive process yields small quantities of extraordinarily concentrated fragrance.'},{h:'Attar in Indian Culture',p:'Attar has been integral to Indian cultural life for centuries. It was offered as a mark of hospitality to guests, worn during religious ceremonies, and used to scent living spaces. The tradition of applying attar before prayer continues in many communities today. Rose attar, sandalwood attar, and mitti attar (the scent of rain on dry earth) remain deeply woven into the sensory memory of the subcontinent.'},{h:'From Tradition to Modern Luxury',p:'The principles that guided attar makers — patience, purity of ingredients, and respect for the raw material — remain relevant in modern Indian perfumery. At The Sixth Ritu, we draw inspiration from this heritage while employing contemporary techniques that allow for greater complexity and consistency. The reverence for craft and the belief that fragrance is more than decoration — it is an expression of culture and identity — connects our work to a lineage that stretches back generations.'}]},{slug:'perfume-layering-guide',tag:'Craft',title:'The Art of Perfume Layering',hero:'/hero-roses.webp',intro:'How to combine fragrances to create something uniquely yours.',body:[{h:'What Is Fragrance Layering?',p:'Layering is the practice of wearing two or more fragrances simultaneously to create a personalised scent that no single fragrance offers on its own. It is an art form practised by fragrance enthusiasts worldwide, and when done thoughtfully, the result can be more interesting and complex than either scent alone. The key is understanding which notes complement each other and which might clash.'},{h:'Principles of Good Layering',p:'Start with the heavier fragrance as your base and apply the lighter one on top. Apply to different pulse points rather than spraying both in the same spot — this allows each fragrance to project independently while blending in the air around you. Begin with just one spray of each and build gradually. Less is always more when layering; you want harmony, not competition.'},{h:'Combinations That Work',p:'Warm and fresh pairings often create beautiful contrast. Try Dark Monsoon on the wrists with Crystal Bloom behind the ears — the deep oud grounds the airy freshness into something sophisticated and unexpected. Golden Ritual layered with Flora Silk creates a comforting floral warmth that is perfect for evenings. Royal Zafran Rose with Golden Leaf produces a rich, spiced-woody combination that feels opulent without being overwhelming.'},{h:'Combinations to Approach with Care',p:'Two fragrances from the same intensity level can compete rather than complement. Layering Dark Monsoon with Golden Leaf, for instance, may create an overly heavy result since both are deep and commanding. Similarly, two fresh fragrances might thin each other out rather than creating depth. The most rewarding combinations typically pair contrast — light with dark, floral with woody, sweet with aromatic.'},{h:'Making It Personal',p:'There are no rigid rules in layering — only guidelines. What smells beautiful to you is the right answer. Experiment on weekends or quiet days when you can pay attention to how the combination evolves. Take notes on what you like and what does not work. Over time, you will develop your own layering instinct, and your fragrance becomes something no one else wears — a true signature.'}]},{slug:'seasons-and-scent-what-to-wear-when',tag:'Season',title:'Seasons and Scent — What to Wear When',hero:'/hero banner 2.webp',intro:'An Indian climate guide to choosing the right fragrance for every time of year.',body:[{h:'Summer: Light, Clean, Alive',p:'Indian summers demand fragrances that cut through the heat rather than adding to it. Fresh, citrus-forward, and aquatic compositions perform beautifully — they feel cooling on the skin and do not become cloying in humidity. Crystal Bloom, with its sea water and lavender opening, is naturally suited to this season. Flora Silk also works well in summer; its bergamot top notes and clean musk base keep it feeling light even as temperatures climb.'},{h:'Monsoon: Earthy and Atmospheric',p:'The monsoon transforms the air itself into something fragrant — wet earth, green leaves, rain on stone. This is the season for fragrances that embrace depth and atmosphere. Dark Monsoon was inspired by exactly this mood — its amber, oud, and suede composition echoes the feeling of a storm settling into the earth. The humidity of monsoon season also enhances projection, so a little goes a long way.'},{h:'Autumn and Early Winter: Warm and Golden',p:'As the air cools and evenings grow longer, warmer fragrances come into their own. This is the season for comfort notes — vanilla, amber, tonka, spice. Golden Ritual, with its tea and vanilla warmth, is perfect for the transition from autumn into winter. Golden Leaf’s agarwood and tonka character also shines in this weather, its warmth becoming more pronounced against cool skin.'},{h:'Deep Winter and Festivities',p:'Winter is the season for the richest, most opulent compositions. Cold air keeps heavy fragrances close to the skin, creating an intimate aura rather than a room-filling projection. Royal Zafran Rose, with its saffron and rose opulence, is ideal for winter celebrations and festive occasions. Dark Monsoon also pairs well with cold weather, its commanding character balanced by the stillness of winter air.'},{h:'Year-Round Signatures',p:'If you prefer a single fragrance regardless of season, look for compositions with enough versatility to work across climates. Golden Ritual and Flora Silk are both adaptable — warm enough for winter yet refined enough for summer. The key is application: use more in cold weather (when scent clings close) and less in heat (when it projects further). Two sprays in winter, one in summer, can make the same fragrance feel appropriate year-round.'}]},{slug:'caring-for-your-luxury-fragrance',tag:'Care',title:'Caring for Your Luxury Fragrance',hero:'/hero banner 3.webp',intro:'How to store, protect, and get the most from every bottle.',body:[{h:'Storage: The Golden Rules',p:'Heat, light, and humidity are the three factors that degrade perfume most quickly. Store your fragrance in a cool, dry place away from direct sunlight — a bedroom drawer or wardrobe shelf is ideal. Avoid keeping bottles in the bathroom, where temperature and humidity fluctuate with every shower. The original box provides additional protection from light, so consider storing the bottle inside it when not in use.'},{h:'Temperature Consistency',p:'Perfume oils are sensitive to temperature swings. Repeated heating and cooling can alter the molecular structure of the fragrance, changing its character over time. A consistent room temperature between 15–25°C is optimal. Never store fragrance in a car, near a window, or on a radiator. If you live in a particularly warm climate, keeping bottles in a dark cupboard on the coolest side of the house makes a noticeable difference in longevity.'},{h:'Maximising Longevity on Skin',p:'Apply fragrance immediately after a shower, when your skin is clean and slightly warm. Moisturised skin holds scent longer — an unscented body lotion or oil applied before spraying creates a base for the fragrance to cling to. Target pulse points where blood vessels sit close to the surface: the inner wrists, behind the ears, the base of the throat, and the inner elbows. Avoid rubbing your wrists together, as this breaks down the top notes prematurely.'},{h:'Travelling with Fragrance',p:'When travelling, keep your fragrance in your carry-on bag rather than checked luggage, where temperature extremes in the aircraft hold can cause damage. If you travel frequently, consider keeping a dedicated travel bottle rather than repeatedly transferring from your main flacon. Wrap the bottle in soft clothing to protect it from impacts. For extended trips, decanting a small amount into an atomiser preserves your main bottle.'},{h:'Shelf Life and When to Replace',p:'A well-stored Extrait de Parfum can maintain its character for three to five years or longer due to its high concentration of oils. Signs that a fragrance has turned include a change in colour (darkening significantly), a shift in the opening smell (becoming vinegary or sharp), or reduced projection. If your fragrance no longer smells the way you remember, it may be time for a fresh bottle.'}]},{slug:'gifting-luxury-perfume',tag:'Gifting',title:'The Art of Gifting Luxury Perfume',hero:'/hero banner 4.webp',intro:'How to choose the perfect fragrance gift for every occasion and every person.',body:[{h:'Why Fragrance Makes a Meaningful Gift',p:'A fragrance is one of the most personal gifts you can give. Unlike a garment or accessory, a perfume becomes part of someone’s identity — it accompanies their most important moments and lingers in the memory of everyone they meet. A well-chosen fragrance says: I thought about who you are, not just what you might need. It is a gift that transforms ordinary days into something more intentional.'},{h:'Choosing for Someone Else',p:'The safest approach is to consider the recipient’s personality rather than trying to guess their taste in notes. For someone bold and confident, Dark Monsoon or Golden Leaf makes a strong statement. For someone elegant and refined, Royal Zafran Rose or Flora Silk conveys sophistication. For someone who values warmth and comfort, Golden Ritual feels like a personal embrace. Crystal Bloom suits the person who is quietly confident and appreciates understated freshness.'},{h:'Gifting by Occasion',p:'Birthdays call for something that reflects the recipient’s character — this is a gift about them, not about the event. Anniversaries and weddings are ideal for opulent choices like Royal Zafran Rose. Festive seasons such as Diwali and Eid are occasions for rich, celebratory fragrances. For a housewarming or thank-you, a universally appealing scent like Golden Ritual or Crystal Bloom is a thoughtful choice that most people would enjoy.'},{h:'Presentation Matters',p:'Every fragrance from The Sixth Ritu arrives in packaging designed to feel like an occasion in itself. The unboxing experience — from the outer sleeve to the inner box to the bottle itself — is crafted to communicate luxury and care. When gifting, let the packaging speak for itself. A simple handwritten note tucked alongside the box adds a personal touch that elevates the gift beyond the product.'},{h:'When in Doubt',p:'If you are truly unsure about someone’s fragrance preferences, consider their lifestyle and wardrobe. Someone who dresses minimally and favours clean lines will likely appreciate Crystal Bloom or Flora Silk. Someone who loves rich fabrics, jewellery, and bold colours might resonate with Dark Monsoon or Royal Zafran Rose. And remember — the fact that you chose a fragrance thoughtfully matters more than whether you guessed the exact right one.'}]}];function journalArticle(a){if(!a)return notFound();const related=products.slice(0,3);return `<main id="main">${pageHero('The Fragrance Journal',a.title,a.intro)}<section class="section"><div class="container journal-article"><p class="crumb"><a href="/" data-link>Home</a> / <a href="/journal" data-link>Journal</a> / ${a.title}</p><div class="journal-hero-img"><img src="${a.hero}" alt="${a.title} \u2014 The Sixth Ritu fragrance journal" loading="lazy"/></div>${a.body.map(b=>`<div class="journal-block"><h3>${b.h}</h3><p>${b.p}</p></div>`).join('')}<div class="journal-related"><p class="eyebrow">Explore Our Fragrances</p><div class="product-grid">${related.map(productCard).join('')}</div></div><div class="journal-nav">${link('/journal','\u2190 Back to Journal','text-link')} ${link('/shop','Shop All Fragrances \u2192','text-link')}</div></div></section></main>`}
function journalIndex(){return `<main id="main">${pageHero('The Fragrance Journal','Stories & Craft.','Explorations in fragrance, ritual, and the art of remembering.')}<section class="section"><div class="container"><div class="v3-journal-grid">${journalArticles.map(j=>`<a class="v3-journal-card" href="/journal/${j.slug}" data-link><div class="v3-journal-card-img"><img src="${j.hero}" alt="${j.title}" loading="lazy"/></div><span class="v3-journal-card-tag">${j.tag}</span><h3>${j.title}</h3><p>${j.intro}</p></a>`).join('')}</div></div></section></main>`}
function notFound(){return `<main id="main" class="not-found"><div><p class="eyebrow">The Season is elsewhere</p><h1>404</h1><h2 class="display" style="font-size:3rem">This page has passed into memory.</h2>${link('/','Return Home','btn')}</div></main>`}
